{
  "name": "DiveLog - Freediving Record",
  "description": "A comprehensive freediving log application to record STA, DYN, FIM, and CWT sessions, track Personal Bests, and manage dive media.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Discipline {
  STA = 'STA',
  DYN = 'DYN',
  FIM = 'FIM',
  CWT = 'CWT'
}

export interface MediaFile {
  id: string;
  type: 'image' | 'video';
  url: string; // Base64 or ObjectURL
}

export interface DiveEntry {
  id: string;
  discipline: Discipline;
  attemptNumber: number;
  timeSeconds?: number; // For STA, FIM, CWT
  distanceMeters?: number; // For DYN
  depthMeters?: number; // For FIM, CWT
  media: MediaFile[];
  note?: string;
  timestamp: number;
}

export interface DiveSession {
  id: string;
  date: string;
  location: string;
  buddy: string;
  note: string;
  entries: DiveEntry[];
}

export interface PersonalBest {
  discipline: Discipline;
  value: string;
  date?: string;
}

import { Discipline, DiveSession, DiveEntry, PersonalBest } from './types';

export const formatTime = (seconds?: number): string => {
  if (seconds === undefined) return '--:--';
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
};

export const calculateSessionPB = (entries: DiveEntry[]): Partial<Record<Discipline, string>> => {
  const pbs: Partial<Record<Discipline, string>> = {};

  entries.forEach(entry => {
    if (entry.discipline === Discipline.STA) {
      const current = entry.timeSeconds || 0;
      const existing = parseInt(pbs[Discipline.STA] || '0');
      if (current > existing) pbs[Discipline.STA] = current.toString();
    } else if (entry.discipline === Discipline.DYN) {
      const current = entry.distanceMeters || 0;
      const existing = parseInt(pbs[Discipline.DYN] || '0');
      if (current > existing) pbs[Discipline.DYN] = current.toString();
    } else {
      // FIM, CWT (Depth is priority)
      const current = entry.depthMeters || 0;
      const existing = parseInt(pbs[entry.discipline] || '0');
      if (current > existing) pbs[entry.discipline] = current.toString();
    }
  });

  // Convert raw numbers back to display strings
  if (pbs[Discipline.STA]) pbs[Discipline.STA] = formatTime(parseInt(pbs[Discipline.STA]!));
  if (pbs[Discipline.DYN]) pbs[Discipline.DYN] = `${pbs[Discipline.DYN]}m`;
  if (pbs[Discipline.FIM]) pbs[Discipline.FIM] = `${pbs[Discipline.FIM]}m`;
  if (pbs[Discipline.CWT]) pbs[Discipline.CWT] = `${pbs[Discipline.CWT]}m`;

  return pbs;
};

export const calculateOverallPB = (sessions: DiveSession[]): PersonalBest[] => {
  const allEntries = sessions.flatMap(s => s.entries.map(e => ({ ...e, sessionDate: s.date })));

  const bests: Record<Discipline, { value: number; date: string }> = {
    [Discipline.STA]: { value: 0, date: '' },
    [Discipline.DYN]: { value: 0, date: '' },
    [Discipline.FIM]: { value: 0, date: '' },
    [Discipline.CWT]: { value: 0, date: '' },
  };

  allEntries.forEach(e => {
    let currentVal = 0;
    if (e.discipline === Discipline.STA) currentVal = e.timeSeconds || 0;
    else if (e.discipline === Discipline.DYN) currentVal = e.distanceMeters || 0;
    else currentVal = e.depthMeters || 0;

    if (currentVal > bests[e.discipline].value) {
      bests[e.discipline] = { value: currentVal, date: e.sessionDate };
    }
  });

  return Object.values(Discipline).map(d => ({
    discipline: d,
    value: d === Discipline.STA ? formatTime(bests[d].value) : (bests[d].value > 0 ? `${bests[d].value}m` : '--'),
    date: bests[d].date
  }));
};

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = error => reject(error);
  });
};

import React, { useState, useEffect, useCallback } from 'react';
import { Plus, Trophy, Calendar, MapPin, Users, ChevronLeft, Trash2, Camera, Play, Image as ImageIcon } from 'lucide-react';
import { Discipline, DiveSession, DiveEntry, MediaFile } from './types';
import { formatTime, calculateOverallPB, calculateSessionPB, fileToBase64 } from './utils';

// Components
const DisciplineBadge = ({ type }: { type: Discipline }) => {
  const colors: Record<Discipline, string> = {
    [Discipline.STA]: 'bg-purple-500/20 text-purple-400 border-purple-500/30',
    [Discipline.DYN]: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    [Discipline.FIM]: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    [Discipline.CWT]: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  };
  return (
    <span className={`px-2 py-0.5 rounded text-[10px] font-bold border uppercase tracking-wider ${colors[type]}`}>
      {type}
    </span>
  );
};

const PBCard = ({ pb }: { pb: { discipline: Discipline; value: string; date?: string } }) => {
  const subText: Record<Discipline, string> = {
    [Discipline.STA]: 'Static Apnea',
    [Discipline.DYN]: 'Dynamic',
    [Discipline.FIM]: 'Free Immersion',
    [Discipline.CWT]: 'Constant Weight',
  };

  return (
    <div className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-2xl flex flex-col justify-between hover:border-purple-500/50 transition-colors">
      <div className="flex justify-between items-start mb-4">
        <DisciplineBadge type={pb.discipline} />
        {pb.date && <span className="text-[10px] text-gray-500 font-medium">{pb.date}</span>}
      </div>
      <div>
        <div className="text-3xl font-bold text-white mb-1">{pb.value}</div>
        <div className="text-xs text-gray-400 font-medium">{subText[pb.discipline]}</div>
      </div>
    </div>
  );
};

const DiveEntryItem = ({ entry, onDelete }: { entry: DiveEntry; onDelete: () => void }) => {
  return (
    <div className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-xl flex flex-col gap-3">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
          <DisciplineBadge type={entry.discipline} />
          <span className="text-xs font-semibold text-gray-400">{entry.attemptNumber}차 시도</span>
        </div>
        <button onClick={onDelete} className="p-1 text-gray-500 hover:text-red-400">
          <Trash2 size={16} />
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {entry.timeSeconds !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Time</div>
            <div className="text-lg font-semibold">{formatTime(entry.timeSeconds)}</div>
          </div>
        )}
        {entry.distanceMeters !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Distance</div>
            <div className="text-lg font-semibold">{entry.distanceMeters}m</div>
          </div>
        )}
        {entry.depthMeters !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Depth</div>
            <div className="text-lg font-semibold">{entry.depthMeters}m</div>
          </div>
        )}
      </div>

      {entry.media.length > 0 && (
        <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
          {entry.media.map(m => (
            <div key={m.id} className="relative w-16 h-16 rounded-md overflow-hidden bg-black flex-shrink-0 group">
              <img src={m.url} className="w-full h-full object-cover opacity-80" alt="Dive media" />
              {m.type === 'video' && <Play size={12} className="absolute inset-0 m-auto text-white fill-white" />}
            </div>
          ))}
        </div>
      )}

      {entry.note && (
        <p className="text-xs text-gray-400 border-t border-[#2d2d3a] pt-2">{entry.note}</p>
      )}
    </div>
  );
};

export default function App() {
  const [sessions, setSessions] = useState<DiveSession[]>([]);
  const [view, setView] = useState<'dashboard' | 'session_detail'>('dashboard');
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDiveModalOpen, setIsDiveModalOpen] = useState(false);

  // Load from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('dive_sessions');
    if (saved) {
      try {
        setSessions(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse sessions", e);
      }
    }
  }, []);

  // Save to localStorage
  useEffect(() => {
    localStorage.setItem('dive_sessions', JSON.stringify(sessions));
  }, [sessions]);

  const overallPB = calculateOverallPB(sessions);

  const handleCreateSession = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newSession: DiveSession = {
      id: Date.now().toString(),
      date: formData.get('date') as string,
      location: formData.get('location') as string,
      buddy: formData.get('buddy') as string,
      note: formData.get('note') as string,
      entries: [],
    };
    setSessions([newSession, ...sessions]);
    setIsModalOpen(false);
    setSelectedSessionId(newSession.id);
    setView('session_detail');
  };

  const handleAddDive = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!selectedSessionId) return;

    const formData = new FormData(e.currentTarget);
    const discipline = formData.get('discipline') as Discipline;
    const session = sessions.find(s => s.id === selectedSessionId);
    if (!session) return;

    const attemptNumber = session.entries.filter(e => e.discipline === discipline).length + 1;

    // Media processing
    const mediaFiles = formData.getAll('media') as File[];
    const processedMedia: MediaFile[] = [];
    for (const f of mediaFiles) {
        if (f.size > 0) {
            const base64 = await fileToBase64(f);
            processedMedia.push({
                id: Math.random().toString(36).substr(2, 9),
                type: f.type.startsWith('video') ? 'video' : 'image',
                url: base64
            });
        }
    }

    const timeStr = formData.get('time') as string;
    let timeSeconds: number | undefined;
    if (timeStr) {
        const [m, s] = timeStr.split(':').map(Number);
        timeSeconds = (m || 0) * 60 + (s || 0);
    }

    const newEntry: DiveEntry = {
      id: Date.now().toString(),
      discipline,
      attemptNumber,
      timeSeconds,
      distanceMeters: formData.get('distance') ? Number(formData.get('distance')) : undefined,
      depthMeters: formData.get('depth') ? Number(formData.get('depth')) : undefined,
      media: processedMedia,
      note: formData.get('note') as string,
      timestamp: Date.now(),
    };

    setSessions(sessions.map(s => 
      s.id === selectedSessionId ? { ...s, entries: [...s.entries, newEntry] } : s
    ));
    setIsDiveModalOpen(false);
  };

  const deleteSession = (id: string) => {
    if (confirm('이 세션을 삭제하시겠습니까?')) {
      setSessions(sessions.filter(s => s.id !== id));
      setView('dashboard');
    }
  };

  const deleteEntry = (sessionId: string, entryId: string) => {
    setSessions(sessions.map(s => 
      s.id === sessionId ? { ...s, entries: s.entries.filter(e => e.id !== entryId) } : s
    ));
  };

  const currentSession = sessions.find(s => s.id === selectedSessionId);
  const sessionPBs = currentSession ? calculateSessionPB(currentSession.entries) : {};

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0f0f17] pb-20 overflow-x-hidden">
      {/* Header */}
      <header className="sticky top-0 z-20 bg-[#0f0f17]/80 backdrop-blur-md px-6 py-4 flex justify-between items-center border-b border-[#1a1a24]">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-purple-600 rounded-xl flex items-center justify-center shadow-lg shadow-purple-900/20">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-white">
              <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" />
              <circle cx="12" cy="12" r="3" />
            </svg>
          </div>
          <div>
            <h1 className="text-lg font-bold leading-tight">DiveLog</h1>
            <p className="text-[10px] text-purple-400 font-bold uppercase tracking-widest">Freediving Log</p>
          </div>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-purple-600 hover:bg-purple-500 text-white font-bold py-2.5 px-5 rounded-xl flex items-center gap-2 shadow-lg shadow-purple-900/40 transition-all active:scale-95"
        >
          <Plus size={18} />
          <span className="text-sm">새 세션</span>
        </button>
      </header>

      {view === 'dashboard' ? (
        <main className="p-6 space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
          {/* Overall PB Section */}
          <section>
            <div className="flex items-center gap-2 mb-4">
              <Trophy size={18} className="text-yellow-500" />
              <h2 className="text-lg font-bold">Overall PB</h2>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {overallPB.map(pb => (
                <PBCard key={pb.discipline} pb={pb} />
              ))}
            </div>
          </section>

          {/* Sessions List */}
          <section>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-bold">다이브 세션</h2>
              <span className="text-xs text-gray-500 font-medium">{sessions.length} sessions</span>
            </div>

            {sessions.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-20 text-center space-y-4">
                <div className="w-16 h-16 bg-[#1a1a24] rounded-full flex items-center justify-center text-gray-600">
                  <Calendar size={32} />
                </div>
                <div>
                  <p className="text-gray-400 font-medium">아직 기록된 세션이 없습니다</p>
                  <p className="text-xs text-gray-600">첫 번째 다이브 세션을 추가해보세요!</p>
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                {sessions.map(session => {
                  const sPBs = calculateSessionPB(session.entries);
                  return (
                    <div 
                      key={session.id} 
                      onClick={() => { setSelectedSessionId(session.id); setView('session_detail'); }}
                      className="bg-[#1a1a24] border border-[#2d2d3a] p-5 rounded-2xl cursor-pointer hover:border-purple-500/40 transition-all active:scale-[0.98]"
                    >
                      <div className="flex justify-between items-start mb-3">
                        <div>
                          <h3 className="font-bold text-lg mb-1">{session.date}</h3>
                          <div className="flex items-center gap-3 text-xs text-gray-400">
                            <span className="flex items-center gap-1"><MapPin size={12} className="text-purple-500" />{session.location}</span>
                            <span className="flex items-center gap-1"><Users size={12} className="text-purple-500" />{session.buddy}</span>
                          </div>
                        </div>
                        <div className="flex gap-1">
                          {Object.keys(sPBs).map(d => (
                            <div key={d} className="w-2 h-2 rounded-full bg-purple-500/50" />
                          ))}
                        </div>
                      </div>

                      <div className="flex gap-2 flex-wrap">
                        {Object.entries(sPBs).map(([disc, val]) => (
                          <div key={disc} className="bg-[#0f0f17] border border-[#2d2d3a] px-2 py-1 rounded-lg flex items-center gap-2">
                            <span className="text-[10px] font-bold text-purple-400">{disc}</span>
                            <span className="text-xs font-bold">{val}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </section>
        </main>
      ) : (
        <main className="p-6 space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
          {/* Session Detail View */}
          <div className="flex items-center justify-between">
            <button onClick={() => setView('dashboard')} className="flex items-center gap-1 text-gray-400 hover:text-white transition-colors">
              <ChevronLeft size={20} />
              <span className="text-sm font-medium">대시보드</span>
            </button>
            <button onClick={() => deleteSession(selectedSessionId!)} className="text-gray-500 hover:text-red-400">
              <Trash2 size={18} />
            </button>
          </div>

          {currentSession && (
            <>
              <div className="space-y-2">
                <h2 className="text-2xl font-bold">{currentSession.date}</h2>
                <div className="flex gap-4 text-xs text-gray-400">
                  <span className="flex items-center gap-1"><MapPin size={14} className="text-purple-500" />{currentSession.location}</span>
                  <span className="flex items-center gap-1"><Users size={14} className="text-purple-500" />{currentSession.buddy}</span>
                </div>
                {currentSession.note && <p className="text-sm text-gray-400 bg-[#1a1a24] p-3 rounded-xl">{currentSession.note}</p>}
              </div>

              {/* Session PBs */}
              <div className="grid grid-cols-2 gap-3">
                {Object.entries(sessionPBs).map(([disc, val]) => (
                  <div key={disc} className="bg-[#1a1a24] border border-[#2d2d3a] p-3 rounded-xl flex items-center justify-between">
                    <span className="text-xs font-bold text-gray-400">{disc} PB</span>
                    <span className="text-sm font-bold text-purple-400">{val}</span>
                  </div>
                ))}
              </div>

              <div className="flex items-center justify-between pt-4 border-t border-[#1a1a24]">
                <h3 className="font-bold">다이브 로그 ({currentSession.entries.length})</h3>
                <button 
                  onClick={() => setIsDiveModalOpen(true)}
                  className="bg-[#1a1a24] border border-[#2d2d3a] text-xs font-bold py-2 px-4 rounded-lg hover:bg-[#2d2d3a] transition-all flex items-center gap-1"
                >
                  <Plus size={14} /> 기록 추가
                </button>
              </div>

              <div className="space-y-4">
                {currentSession.entries.length === 0 ? (
                  <p className="text-center py-10 text-gray-500 text-sm italic">기록된 다이브가 없습니다.</p>
                ) : (
                  [...currentSession.entries].sort((a,b) => b.timestamp - a.timestamp).map(entry => (
                    <DiveEntryItem 
                        key={entry.id} 
                        entry={entry} 
                        onDelete={() => deleteEntry(selectedSessionId!, entry.id)} 
                    />
                  ))
                )}
              </div>
            </>
          )}
        </main>
      )}

      {/* New Session Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-3xl p-6 border border-[#2d2d3a] animate-in zoom-in-95 duration-200">
            <h2 className="text-xl font-bold mb-6">새 다이브 세션</h2>
            <form onSubmit={handleCreateSession} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">날짜</label>
                <input required type="date" name="date" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" defaultValue={new Date().toISOString().split('T')[0]} />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">장소</label>
                <input required type="text" name="location" placeholder="K2, 파라다이스, 올림픽수영장 등" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">버디</label>
                <input required type="text" name="buddy" placeholder="함께한 사람 이름" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">메모</label>
                <textarea name="note" rows={2} placeholder="오늘의 컨디션이나 특이사항" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500 resize-none"></textarea>
              </div>
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 text-sm font-bold text-gray-400 py-3 rounded-xl hover:bg-[#2d2d3a]">취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 text-sm font-bold text-white py-3 rounded-xl hover:bg-purple-500 shadow-lg shadow-purple-900/30">세션 시작하기</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Add Dive Modal */}
      {isDiveModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-3xl p-6 border border-[#2d2d3a] animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-6">기록 추가</h2>
            <form onSubmit={handleAddDive} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">종목</label>
                <select name="discipline" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500 appearance-none" required defaultValue={Discipline.STA}>
                  <option value={Discipline.STA}>STA (Static Apnea)</option>
                  <option value={Discipline.DYN}>DYN (Dynamic)</option>
                  <option value={Discipline.FIM}>FIM (Free Immersion)</option>
                  <option value={Discipline.CWT}>CWT (Constant Weight)</option>
                </select>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">시간 (MM:SS)</label>
                  <input type="text" name="time" placeholder="00:00" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
                </div>
                <div>
                  <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">거리 (m)</label>
                  <input type="number" name="distance" placeholder="0" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
                </div>
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">깊이 (m)</label>
                <input type="number" name="depth" placeholder="0" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">사진/영상</label>
                <div className="relative group">
                  <input type="file" name="media" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer z-10" />
                  <div className="bg-[#0f0f17] border border-[#2d2d3a] border-dashed rounded-xl px-4 py-6 flex flex-col items-center gap-2 group-hover:border-purple-500 transition-colors">
                    <Camera className="text-gray-500 group-hover:text-purple-500" />
                    <span className="text-xs text-gray-500">미디어 업로드</span>
                  </div>
                </div>
                <p className="text-[10px] text-gray-600 mt-1">* 브라우저 환경상 큰 파일은 저장이 제한될 수 있습니다.</p>
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">메모</label>
                <input type="text" name="note" placeholder="간단한 소감" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>

              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setIsDiveModalOpen(false)} className="flex-1 text-sm font-bold text-gray-400 py-3 rounded-xl hover:bg-[#2d2d3a]">취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 text-sm font-bold text-white py-3 rounded-xl hover:bg-purple-500">기록 저장</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { Plus, Trophy, Calendar, MapPin, Users, ChevronLeft, Trash2, Camera, Play, Image as ImageIcon } from 'lucide-react';
import { Discipline, DiveSession, DiveEntry, MediaFile, PersonalBest } from './types';
import { formatTime, calculateOverallPB, calculateSessionPB, fileToBase64 } from './utils';

// Components
// Added explicit React.FC typing to resolve "key" prop error in JSX lists
const DisciplineBadge: React.FC<{ type: Discipline }> = ({ type }) => {
  const colors: Record<Discipline, string> = {
    [Discipline.STA]: 'bg-purple-500/20 text-purple-400 border-purple-500/30',
    [Discipline.DYN]: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    [Discipline.FIM]: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    [Discipline.CWT]: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  };
  return (
    <span className={`px-2 py-0.5 rounded text-[10px] font-bold border uppercase tracking-wider ${colors[type]}`}>
      {type}
    </span>
  );
};

// Added explicit React.FC typing to resolve "key" prop error in JSX lists
const PBCard: React.FC<{ pb: PersonalBest }> = ({ pb }) => {
  const subText: Record<Discipline, string> = {
    [Discipline.STA]: 'Static Apnea',
    [Discipline.DYN]: 'Dynamic',
    [Discipline.FIM]: 'Free Immersion',
    [Discipline.CWT]: 'Constant Weight',
  };

  return (
    <div className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-2xl flex flex-col justify-between hover:border-purple-500/50 transition-colors">
      <div className="flex justify-between items-start mb-4">
        <DisciplineBadge type={pb.discipline} />
        {pb.date && <span className="text-[10px] text-gray-500 font-medium">{pb.date}</span>}
      </div>
      <div>
        <div className="text-3xl font-bold text-white mb-1">{pb.value}</div>
        <div className="text-xs text-gray-400 font-medium">{subText[pb.discipline]}</div>
      </div>
    </div>
  );
};

// Added explicit React.FC typing to resolve "key" prop error in JSX lists
const DiveEntryItem: React.FC<{ entry: DiveEntry; onDelete: () => void }> = ({ entry, onDelete }) => {
  return (
    <div className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-xl flex flex-col gap-3">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
          <DisciplineBadge type={entry.discipline} />
          <span className="text-xs font-semibold text-gray-400">{entry.attemptNumber}차 시도</span>
        </div>
        <button onClick={onDelete} className="p-1 text-gray-500 hover:text-red-400">
          <Trash2 size={16} />
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {entry.timeSeconds !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Time</div>
            <div className="text-lg font-semibold">{formatTime(entry.timeSeconds)}</div>
          </div>
        )}
        {entry.distanceMeters !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Distance</div>
            <div className="text-lg font-semibold">{entry.distanceMeters}m</div>
          </div>
        )}
        {entry.depthMeters !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Depth</div>
            <div className="text-lg font-semibold">{entry.depthMeters}m</div>
          </div>
        )}
      </div>

      {entry.media.length > 0 && (
        <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
          {entry.media.map(m => (
            <div key={m.id} className="relative w-16 h-16 rounded-md overflow-hidden bg-black flex-shrink-0 group">
              <img src={m.url} className="w-full h-full object-cover opacity-80" alt="Dive media" />
              {m.type === 'video' && <Play size={12} className="absolute inset-0 m-auto text-white fill-white" />}
            </div>
          ))}
        </div>
      )}

      {entry.note && (
        <p className="text-xs text-gray-400 border-t border-[#2d2d3a] pt-2">{entry.note}</p>
      )}
    </div>
  );
};

export default function App() {
  const [sessions, setSessions] = useState<DiveSession[]>([]);
  const [view, setView] = useState<'dashboard' | 'session_detail'>('dashboard');
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDiveModalOpen, setIsDiveModalOpen] = useState(false);

  // Load from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('dive_sessions');
    if (saved) {
      try {
        setSessions(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse sessions", e);
      }
    }
  }, []);

  // Save to localStorage
  useEffect(() => {
    localStorage.setItem('dive_sessions', JSON.stringify(sessions));
  }, [sessions]);

  const overallPB = calculateOverallPB(sessions);

  const handleCreateSession = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newSession: DiveSession = {
      id: Date.now().toString(),
      date: formData.get('date') as string,
      location: formData.get('location') as string,
      buddy: formData.get('buddy') as string,
      note: formData.get('note') as string,
      entries: [],
    };
    setSessions([newSession, ...sessions]);
    setIsModalOpen(false);
    setSelectedSessionId(newSession.id);
    setView('session_detail');
  };

  const handleAddDive = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!selectedSessionId) return;

    const formData = new FormData(e.currentTarget);
    const discipline = formData.get('discipline') as Discipline;
    const session = sessions.find(s => s.id === selectedSessionId);
    if (!session) return;

    const attemptNumber = session.entries.filter(e => e.discipline === discipline).length + 1;

    // Media processing
    const mediaFiles = formData.getAll('media') as File[];
    const processedMedia: MediaFile[] = [];
    for (const f of mediaFiles) {
        if (f.size > 0) {
            const base64 = await fileToBase64(f);
            processedMedia.push({
                id: Math.random().toString(36).substr(2, 9),
                type: f.type.startsWith('video') ? 'video' : 'image',
                url: base64
            });
        }
    }

    const timeStr = formData.get('time') as string;
    let timeSeconds: number | undefined;
    if (timeStr) {
        const [m, s] = timeStr.split(':').map(Number);
        timeSeconds = (m || 0) * 60 + (s || 0);
    }

    const newEntry: DiveEntry = {
      id: Date.now().toString(),
      discipline,
      attemptNumber,
      timeSeconds,
      distanceMeters: formData.get('distance') ? Number(formData.get('distance')) : undefined,
      depthMeters: formData.get('depth') ? Number(formData.get('depth')) : undefined,
      media: processedMedia,
      note: formData.get('note') as string,
      timestamp: Date.now(),
    };

    setSessions(sessions.map(s => 
      s.id === selectedSessionId ? { ...s, entries: [...s.entries, newEntry] } : s
    ));
    setIsDiveModalOpen(false);
  };

  const deleteSession = (id: string) => {
    if (confirm('이 세션을 삭제하시겠습니까?')) {
      setSessions(sessions.filter(s => s.id !== id));
      setView('dashboard');
    }
  };

  const deleteEntry = (sessionId: string, entryId: string) => {
    setSessions(sessions.map(s => 
      s.id === sessionId ? { ...s, entries: s.entries.filter(e => e.id !== entryId) } : s
    ));
  };

  const currentSession = sessions.find(s => s.id === selectedSessionId);
  const sessionPBs = currentSession ? calculateSessionPB(currentSession.entries) : {};

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0f0f17] pb-20 overflow-x-hidden">
      {/* Header */}
      <header className="sticky top-0 z-20 bg-[#0f0f17]/80 backdrop-blur-md px-6 py-4 flex justify-between items-center border-b border-[#1a1a24]">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-purple-600 rounded-xl flex items-center justify-center shadow-lg shadow-purple-900/20">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-white">
              <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" />
              <circle cx="12" cy="12" r="3" />
            </svg>
          </div>
          <div>
            <h1 className="text-lg font-bold leading-tight">DiveLog</h1>
            <p className="text-[10px] text-purple-400 font-bold uppercase tracking-widest">Freediving Log</p>
          </div>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-purple-600 hover:bg-purple-500 text-white font-bold py-2.5 px-5 rounded-xl flex items-center gap-2 shadow-lg shadow-purple-900/40 transition-all active:scale-95"
        >
          <Plus size={18} />
          <span className="text-sm">새 세션</span>
        </button>
      </header>

      {view === 'dashboard' ? (
        <main className="p-6 space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
          {/* Overall PB Section */}
          <section>
            <div className="flex items-center gap-2 mb-4">
              <Trophy size={18} className="text-yellow-500" />
              <h2 className="text-lg font-bold">Overall PB</h2>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {overallPB.map(pb => (
                <PBCard key={pb.discipline} pb={pb} />
              ))}
            </div>
          </section>

          {/* Sessions List */}
          <section>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-bold">다이브 세션</h2>
              <span className="text-xs text-gray-500 font-medium">{sessions.length} sessions</span>
            </div>

            {sessions.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-20 text-center space-y-4">
                <div className="w-16 h-16 bg-[#1a1a24] rounded-full flex items-center justify-center text-gray-600">
                  <Calendar size={32} />
                </div>
                <div>
                  <p className="text-gray-400 font-medium">아직 기록된 세션이 없습니다</p>
                  <p className="text-xs text-gray-600">첫 번째 다이브 세션을 추가해보세요!</p>
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                {sessions.map(session => {
                  const sPBs = calculateSessionPB(session.entries);
                  return (
                    <div 
                      key={session.id} 
                      onClick={() => { setSelectedSessionId(session.id); setView('session_detail'); }}
                      className="bg-[#1a1a24] border border-[#2d2d3a] p-5 rounded-2xl cursor-pointer hover:border-purple-500/40 transition-all active:scale-[0.98]"
                    >
                      <div className="flex justify-between items-start mb-3">
                        <div>
                          <h3 className="font-bold text-lg mb-1">{session.date}</h3>
                          <div className="flex items-center gap-3 text-xs text-gray-400">
                            <span className="flex items-center gap-1"><MapPin size={12} className="text-purple-500" />{session.location}</span>
                            <span className="flex items-center gap-1"><Users size={12} className="text-purple-500" />{session.buddy}</span>
                          </div>
                        </div>
                        <div className="flex gap-1">
                          {Object.keys(sPBs).map(d => (
                            <div key={d} className="w-2 h-2 rounded-full bg-purple-500/50" />
                          ))}
                        </div>
                      </div>

                      <div className="flex gap-2 flex-wrap">
                        {Object.entries(sPBs).map(([disc, val]) => (
                          <div key={disc} className="bg-[#0f0f17] border border-[#2d2d3a] px-2 py-1 rounded-lg flex items-center gap-2">
                            <span className="text-[10px] font-bold text-purple-400">{disc}</span>
                            <span className="text-xs font-bold">{val}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </section>
        </main>
      ) : (
        <main className="p-6 space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
          {/* Session Detail View */}
          <div className="flex items-center justify-between">
            <button onClick={() => setView('dashboard')} className="flex items-center gap-1 text-gray-400 hover:text-white transition-colors">
              <ChevronLeft size={20} />
              <span className="text-sm font-medium">대시보드</span>
            </button>
            <button onClick={() => deleteSession(selectedSessionId!)} className="text-gray-500 hover:text-red-400">
              <Trash2 size={18} />
            </button>
          </div>

          {currentSession && (
            <>
              <div className="space-y-2">
                <h2 className="text-2xl font-bold">{currentSession.date}</h2>
                <div className="flex gap-4 text-xs text-gray-400">
                  <span className="flex items-center gap-1"><MapPin size={14} className="text-purple-500" />{currentSession.location}</span>
                  <span className="flex items-center gap-1"><Users size={14} className="text-purple-500" />{currentSession.buddy}</span>
                </div>
                {currentSession.note && <p className="text-sm text-gray-400 bg-[#1a1a24] p-3 rounded-xl">{currentSession.note}</p>}
              </div>

              {/* Session PBs */}
              <div className="grid grid-cols-2 gap-3">
                {Object.entries(sessionPBs).map(([disc, val]) => (
                  <div key={disc} className="bg-[#1a1a24] border border-[#2d2d3a] p-3 rounded-xl flex items-center justify-between">
                    <span className="text-xs font-bold text-gray-400">{disc} PB</span>
                    <span className="text-sm font-bold text-purple-400">{val}</span>
                  </div>
                ))}
              </div>

              <div className="flex items-center justify-between pt-4 border-t border-[#1a1a24]">
                <h3 className="font-bold">다이브 로그 ({currentSession.entries.length})</h3>
                <button 
                  onClick={() => setIsDiveModalOpen(true)}
                  className="bg-[#1a1a24] border border-[#2d2d3a] text-xs font-bold py-2 px-4 rounded-lg hover:bg-[#2d2d3a] transition-all flex items-center gap-1"
                >
                  <Plus size={14} /> 기록 추가
                </button>
              </div>

              <div className="space-y-4">
                {currentSession.entries.length === 0 ? (
                  <p className="text-center py-10 text-gray-500 text-sm italic">기록된 다이브가 없습니다.</p>
                ) : (
                  [...currentSession.entries].sort((a,b) => b.timestamp - a.timestamp).map(entry => (
                    <DiveEntryItem 
                        key={entry.id} 
                        entry={entry} 
                        onDelete={() => deleteEntry(selectedSessionId!, entry.id)} 
                    />
                  ))
                )}
              </div>
            </>
          )}
        </main>
      )}

      {/* New Session Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-3xl p-6 border border-[#2d2d3a] animate-in zoom-in-95 duration-200">
            <h2 className="text-xl font-bold mb-6">새 다이브 세션</h2>
            <form onSubmit={handleCreateSession} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">날짜</label>
                <input required type="date" name="date" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" defaultValue={new Date().toISOString().split('T')[0]} />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">장소</label>
                <input required type="text" name="location" placeholder="K2, 파라다이스, 올림픽수영장 등" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">버디</label>
                <input required type="text" name="buddy" placeholder="함께한 사람 이름" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">메모</label>
                <textarea name="note" rows={2} placeholder="오늘의 컨디션이나 특이사항" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500 resize-none"></textarea>
              </div>
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 text-sm font-bold text-gray-400 py-3 rounded-xl hover:bg-[#2d2d3a]">취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 text-sm font-bold text-white py-3 rounded-xl hover:bg-purple-500 shadow-lg shadow-purple-900/30">세션 시작하기</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Add Dive Modal */}
      {isDiveModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-3xl p-6 border border-[#2d2d3a] animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-6">기록 추가</h2>
            <form onSubmit={handleAddDive} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">종목</label>
                <select name="discipline" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500 appearance-none" required defaultValue={Discipline.STA}>
                  <option value={Discipline.STA}>STA (Static Apnea)</option>
                  <option value={Discipline.DYN}>DYN (Dynamic)</option>
                  <option value={Discipline.FIM}>FIM (Free Immersion)</option>
                  <option value={Discipline.CWT}>CWT (Constant Weight)</option>
                </select>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">시간 (MM:SS)</label>
                  <input type="text" name="time" placeholder="00:00" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
                </div>
                <div>
                  <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">거리 (m)</label>
                  <input type="number" name="distance" placeholder="0" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
                </div>
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">깊이 (m)</label>
                <input type="number" name="depth" placeholder="0" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">사진/영상</label>
                <div className="relative group">
                  <input type="file" name="media" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer z-10" />
                  <div className="bg-[#0f0f17] border border-[#2d2d3a] border-dashed rounded-xl px-4 py-6 flex flex-col items-center gap-2 group-hover:border-purple-500 transition-colors">
                    <Camera className="text-gray-500 group-hover:text-purple-500" />
                    <span className="text-xs text-gray-500">미디어 업로드</span>
                  </div>
                </div>
                <p className="text-[10px] text-gray-600 mt-1">* 브라우저 환경상 큰 파일은 저장이 제한될 수 있습니다.</p>
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">메모</label>
                <input type="text" name="note" placeholder="간단한 소감" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>

              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setIsDiveModalOpen(false)} className="flex-1 text-sm font-bold text-gray-400 py-3 rounded-xl hover:bg-[#2d2d3a]">취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 text-sm font-bold text-white py-3 rounded-xl hover:bg-purple-500">기록 저장</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export enum Discipline {
  STA = 'STA',
  DYN = 'DYN',
  FIM = 'FIM',
  CWT = 'CWT'
}

export interface MediaFile {
  id: string;
  type: 'image' | 'video';
  url: string; // Base64 (local) or Google Drive URL
  driveFileId?: string; // ID of the file in Google Drive
}

export interface DiveEntry {
  id: string;
  discipline: Discipline;
  attemptNumber: number;
  timeSeconds?: number;
  distanceMeters?: number;
  depthMeters?: number;
  media: MediaFile[];
  note?: string;
  timestamp: number;
}

export interface DiveSession {
  id: string;
  date: string;
  location: string;
  buddy: string;
  note: string;
  entries: DiveEntry[];
}

export interface PersonalBest {
  discipline: Discipline;
  value: string;
  date?: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { Plus, Trophy, Calendar, MapPin, Users, ChevronLeft, Trash2, Camera, Play, Cloud, CloudOff, Loader2, ExternalLink } from 'lucide-react';
import { Discipline, DiveSession, DiveEntry, MediaFile, PersonalBest } from './types';
import { formatTime, calculateOverallPB, calculateSessionPB, fileToBase64 } from './utils';

// Constants for Google Drive
const DRIVE_FOLDER_ID = '1Kcx0f-fqKsnYzof58Gg5gMZfKaeg4e_x';
const CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com'; // User needs to provide this for real functionality
const SCOPES = 'https://www.googleapis.com/auth/drive.file';

// Components
const DisciplineBadge: React.FC<{ type: Discipline }> = ({ type }) => {
  const colors: Record<Discipline, string> = {
    [Discipline.STA]: 'bg-purple-500/20 text-purple-400 border-purple-500/30',
    [Discipline.DYN]: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    [Discipline.FIM]: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    [Discipline.CWT]: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  };
  return (
    <span className={`px-2 py-0.5 rounded text-[10px] font-bold border uppercase tracking-wider ${colors[type]}`}>
      {type}
    </span>
  );
};

const PBCard: React.FC<{ pb: PersonalBest }> = ({ pb }) => {
  const subText: Record<Discipline, string> = {
    [Discipline.STA]: 'Static Apnea',
    [Discipline.DYN]: 'Dynamic',
    [Discipline.FIM]: 'Free Immersion',
    [Discipline.CWT]: 'Constant Weight',
  };

  return (
    <div className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-2xl flex flex-col justify-between hover:border-purple-500/50 transition-colors">
      <div className="flex justify-between items-start mb-4">
        <DisciplineBadge type={pb.discipline} />
        {pb.date && <span className="text-[10px] text-gray-500 font-medium">{pb.date}</span>}
      </div>
      <div>
        <div className="text-3xl font-bold text-white mb-1">{pb.value}</div>
        <div className="text-xs text-gray-400 font-medium">{subText[pb.discipline]}</div>
      </div>
    </div>
  );
};

const DiveEntryItem: React.FC<{ entry: DiveEntry; onDelete: () => void }> = ({ entry, onDelete }) => {
  return (
    <div className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-xl flex flex-col gap-3">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
          <DisciplineBadge type={entry.discipline} />
          <span className="text-xs font-semibold text-gray-400">{entry.attemptNumber}차 시도</span>
        </div>
        <button onClick={onDelete} className="p-1 text-gray-500 hover:text-red-400">
          <Trash2 size={16} />
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {entry.timeSeconds !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Time</div>
            <div className="text-lg font-semibold">{formatTime(entry.timeSeconds)}</div>
          </div>
        )}
        {entry.distanceMeters !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Distance</div>
            <div className="text-lg font-semibold">{entry.distanceMeters}m</div>
          </div>
        )}
        {entry.depthMeters !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Depth</div>
            <div className="text-lg font-semibold">{entry.depthMeters}m</div>
          </div>
        )}
      </div>

      {entry.media.length > 0 && (
        <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
          {entry.media.map(m => (
            <div key={m.id} className="relative w-16 h-16 rounded-md overflow-hidden bg-black flex-shrink-0 group">
              {m.driveFileId ? (
                <div className="w-full h-full flex flex-col items-center justify-center bg-blue-900/20 text-blue-400">
                  <Cloud size={20} />
                  <a href={m.url} target="_blank" rel="noopener noreferrer" className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                    <ExternalLink size={16} />
                  </a>
                </div>
              ) : (
                <img src={m.url} className="w-full h-full object-cover opacity-80" alt="Dive media" />
              )}
              {m.type === 'video' && !m.driveFileId && <Play size={12} className="absolute inset-0 m-auto text-white fill-white" />}
            </div>
          ))}
        </div>
      )}

      {entry.note && (
        <p className="text-xs text-gray-400 border-t border-[#2d2d3a] pt-2">{entry.note}</p>
      )}
    </div>
  );
};

export default function App() {
  const [sessions, setSessions] = useState<DiveSession[]>([]);
  const [view, setView] = useState<'dashboard' | 'session_detail'>('dashboard');
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDiveModalOpen, setIsDiveModalOpen] = useState(false);
  const [isUploading, setIsUploading] = useState(false);

  // Google Auth State
  const [accessToken, setAccessToken] = useState<string | null>(null);
  const tokenClientRef = useRef<any>(null);

  // Load from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('dive_sessions');
    if (saved) {
      try {
        setSessions(JSON.parse(saved));
      } catch (e) { console.error(e); }
    }

    // Initialize Google Identity Services
    const initGis = () => {
      if (window.google) {
        tokenClientRef.current = window.google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: (response: any) => {
            if (response.access_token) {
              setAccessToken(response.access_token);
            }
          },
        });
      }
    };

    const checkGis = setInterval(() => {
        if (window.google) {
            initGis();
            clearInterval(checkGis);
        }
    }, 500);

    return () => clearInterval(checkGis);
  }, []);

  // Save to localStorage
  useEffect(() => {
    localStorage.setItem('dive_sessions', JSON.stringify(sessions));
  }, [sessions]);

  const handleDriveAuth = () => {
    if (tokenClientRef.current) {
      tokenClientRef.current.requestAccessToken();
    } else {
      alert("구글 API 라이브러리를 불러오는 중입니다. 잠시 후 다시 시도해주세요.");
    }
  };

  const uploadToDrive = async (file: File, name: string): Promise<string | null> => {
    if (!accessToken) return null;

    const metadata = {
      name: name,
      parents: [DRIVE_FOLDER_ID],
    };

    const formData = new FormData();
    formData.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    formData.append('file', file);

    try {
      const response = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,webViewLink', {
        method: 'POST',
        headers: new Headers({ 'Authorization': 'Bearer ' + accessToken }),
        body: formData,
      });
      const data = await response.json();
      return data.id ? data.webViewLink : null;
    } catch (error) {
      console.error('Upload failed:', error);
      return null;
    }
  };

  const overallPB = calculateOverallPB(sessions);

  const handleCreateSession = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newSession: DiveSession = {
      id: Date.now().toString(),
      date: formData.get('date') as string,
      location: formData.get('location') as string,
      buddy: formData.get('buddy') as string,
      note: formData.get('note') as string,
      entries: [],
    };
    setSessions([newSession, ...sessions]);
    setIsModalOpen(false);
    setSelectedSessionId(newSession.id);
    setView('session_detail');
  };

  const handleAddDive = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!selectedSessionId) return;

    const formData = new FormData(e.currentTarget);
    const discipline = formData.get('discipline') as Discipline;
    const session = sessions.find(s => s.id === selectedSessionId);
    if (!session) return;

    const attemptNumber = session.entries.filter(e => e.discipline === discipline).length + 1;

    // Media processing
    const mediaFiles = formData.getAll('media') as File[];
    const processedMedia: MediaFile[] = [];

    if (mediaFiles.length > 0 && mediaFiles[0].size > 0) {
        setIsUploading(true);
        for (const f of mediaFiles) {
            if (f.size > 0) {
                // If connected to Drive, upload there. Otherwise, use Base64
                let driveUrl: string | null = null;
                const fileName = `${session.date} ${discipline}_${attemptNumber}`;

                if (accessToken) {
                    driveUrl = await uploadToDrive(f, fileName);
                }

                if (driveUrl) {
                    processedMedia.push({
                        id: Math.random().toString(36).substr(2, 9),
                        type: f.type.startsWith('video') ? 'video' : 'image',
                        url: driveUrl,
                        driveFileId: 'uploaded'
                    });
                } else {
                    const base64 = await fileToBase64(f);
                    processedMedia.push({
                        id: Math.random().toString(36).substr(2, 9),
                        type: f.type.startsWith('video') ? 'video' : 'image',
                        url: base64
                    });
                }
            }
        }
        setIsUploading(false);
    }

    const timeStr = formData.get('time') as string;
    let timeSeconds: number | undefined;
    if (timeStr) {
        const [m, s] = timeStr.split(':').map(Number);
        timeSeconds = (m || 0) * 60 + (s || 0);
    }

    const newEntry: DiveEntry = {
      id: Date.now().toString(),
      discipline,
      attemptNumber,
      timeSeconds,
      distanceMeters: formData.get('distance') ? Number(formData.get('distance')) : undefined,
      depthMeters: formData.get('depth') ? Number(formData.get('depth')) : undefined,
      media: processedMedia,
      note: formData.get('note') as string,
      timestamp: Date.now(),
    };

    setSessions(sessions.map(s => 
      s.id === selectedSessionId ? { ...s, entries: [...s.entries, newEntry] } : s
    ));
    setIsDiveModalOpen(false);
  };

  const deleteSession = (id: string) => {
    if (confirm('이 세션을 삭제하시겠습니까?')) {
      setSessions(sessions.filter(s => s.id !== id));
      setView('dashboard');
    }
  };

  const deleteEntry = (sessionId: string, entryId: string) => {
    setSessions(sessions.map(s => 
      s.id === sessionId ? { ...s, entries: s.entries.filter(e => e.id !== entryId) } : s
    ));
  };

  const currentSession = sessions.find(s => s.id === selectedSessionId);
  const sessionPBs = currentSession ? calculateSessionPB(currentSession.entries) : {};

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0f0f17] pb-20 overflow-x-hidden">
      {/* Header */}
      <header className="sticky top-0 z-20 bg-[#0f0f17]/80 backdrop-blur-md px-6 py-4 flex justify-between items-center border-b border-[#1a1a24]">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-purple-600 rounded-xl flex items-center justify-center shadow-lg shadow-purple-900/20">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-white">
              <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" />
              <circle cx="12" cy="12" r="3" />
            </svg>
          </div>
          <div>
            <h1 className="text-lg font-bold leading-tight">DiveLog</h1>
            <button 
                onClick={handleDriveAuth}
                className="flex items-center gap-1.5 text-[9px] font-bold uppercase tracking-wider transition-colors"
                style={{ color: accessToken ? '#4ade80' : '#6b7280' }}
            >
                {accessToken ? <Cloud size={10} /> : <CloudOff size={10} />}
                {accessToken ? 'Drive Synced' : 'Drive Off'}
            </button>
          </div>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-purple-600 hover:bg-purple-500 text-white font-bold py-2.5 px-5 rounded-xl flex items-center gap-2 shadow-lg shadow-purple-900/40 transition-all active:scale-95"
        >
          <Plus size={18} />
          <span className="text-sm">새 세션</span>
        </button>
      </header>

      {view === 'dashboard' ? (
        <main className="p-6 space-y-8">
          <section>
            <div className="flex items-center gap-2 mb-4">
              <Trophy size={18} className="text-yellow-500" />
              <h2 className="text-lg font-bold">Overall PB</h2>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {overallPB.map(pb => (
                <PBCard key={pb.discipline} pb={pb} />
              ))}
            </div>
          </section>

          <section>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-bold">다이브 세션</h2>
              <span className="text-xs text-gray-500 font-medium">{sessions.length} sessions</span>
            </div>

            {sessions.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-20 text-center space-y-4 opacity-50">
                <Calendar size={48} className="text-gray-700" />
                <p className="text-gray-400 font-medium">아직 기록된 세션이 없습니다</p>
              </div>
            ) : (
              <div className="space-y-4">
                {sessions.map(session => {
                  const sPBs = calculateSessionPB(session.entries);
                  return (
                    <div 
                      key={session.id} 
                      onClick={() => { setSelectedSessionId(session.id); setView('session_detail'); }}
                      className="bg-[#1a1a24] border border-[#2d2d3a] p-5 rounded-2xl cursor-pointer hover:border-purple-500/40 transition-all active:scale-[0.98]"
                    >
                      <div className="flex justify-between items-start mb-3">
                        <div>
                          <h3 className="font-bold text-lg mb-1">{session.date}</h3>
                          <div className="flex items-center gap-3 text-xs text-gray-400">
                            <span className="flex items-center gap-1"><MapPin size={12} className="text-purple-500" />{session.location}</span>
                            <span className="flex items-center gap-1"><Users size={12} className="text-purple-500" />{session.buddy}</span>
                          </div>
                        </div>
                      </div>
                      <div className="flex gap-2 flex-wrap">
                        {Object.entries(sPBs).map(([disc, val]) => (
                          <div key={disc} className="bg-[#0f0f17] border border-[#2d2d3a] px-2 py-1 rounded-lg flex items-center gap-2">
                            <span className="text-[10px] font-bold text-purple-400">{disc}</span>
                            <span className="text-xs font-bold">{val}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </section>
        </main>
      ) : (
        <main className="p-6 space-y-6">
          <div className="flex items-center justify-between">
            <button onClick={() => setView('dashboard')} className="flex items-center gap-1 text-gray-400 hover:text-white transition-colors">
              <ChevronLeft size={20} />
              <span className="text-sm font-medium">대시보드</span>
            </button>
            <button onClick={() => deleteSession(selectedSessionId!)} className="text-gray-500 hover:text-red-400">
              <Trash2 size={18} />
            </button>
          </div>

          {currentSession && (
            <>
              <div className="space-y-2">
                <h2 className="text-2xl font-bold">{currentSession.date}</h2>
                <div className="flex gap-4 text-xs text-gray-400">
                  <span className="flex items-center gap-1"><MapPin size={14} className="text-purple-500" />{currentSession.location}</span>
                  <span className="flex items-center gap-1"><Users size={14} className="text-purple-500" />{currentSession.buddy}</span>
                </div>
                {currentSession.note && <p className="text-sm text-gray-400 bg-[#1a1a24] p-3 rounded-xl">{currentSession.note}</p>}
              </div>

              <div className="grid grid-cols-2 gap-3">
                {Object.entries(sessionPBs).map(([disc, val]) => (
                  <div key={disc} className="bg-[#1a1a24] border border-[#2d2d3a] p-3 rounded-xl flex items-center justify-between">
                    <span className="text-xs font-bold text-gray-400">{disc} PB</span>
                    <span className="text-sm font-bold text-purple-400">{val}</span>
                  </div>
                ))}
              </div>

              <div className="flex items-center justify-between pt-4 border-t border-[#1a1a24]">
                <h3 className="font-bold">다이브 로그 ({currentSession.entries.length})</h3>
                <button 
                  onClick={() => setIsDiveModalOpen(true)}
                  className="bg-[#1a1a24] border border-[#2d2d3a] text-xs font-bold py-2 px-4 rounded-lg hover:bg-[#2d2d3a] transition-all flex items-center gap-1"
                >
                  <Plus size={14} /> 기록 추가
                </button>
              </div>

              <div className="space-y-4">
                {currentSession.entries.length === 0 ? (
                  <p className="text-center py-10 text-gray-500 text-sm italic">기록된 다이브가 없습니다.</p>
                ) : (
                  [...currentSession.entries].sort((a,b) => b.timestamp - a.timestamp).map(entry => (
                    <DiveEntryItem 
                        key={entry.id} 
                        entry={entry} 
                        onDelete={() => deleteEntry(selectedSessionId!, entry.id)} 
                    />
                  ))
                )}
              </div>
            </>
          )}
        </main>
      )}

      {/* New Session Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-3xl p-6 border border-[#2d2d3a]">
            <h2 className="text-xl font-bold mb-6">새 다이브 세션</h2>
            <form onSubmit={handleCreateSession} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">날짜</label>
                <input required type="date" name="date" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" defaultValue={new Date().toISOString().split('T')[0]} />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">장소</label>
                <input required type="text" name="location" placeholder="K2, 파라다이스, 올림픽수영장 등" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">버디</label>
                <input required type="text" name="buddy" placeholder="함께한 사람 이름" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">메모</label>
                <textarea name="note" rows={2} placeholder="오늘의 컨디션이나 특이사항" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500 resize-none"></textarea>
              </div>
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 text-sm font-bold text-gray-400 py-3 rounded-xl hover:bg-[#2d2d3a]">취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 text-sm font-bold text-white py-3 rounded-xl hover:bg-purple-500 shadow-lg shadow-purple-900/30">세션 시작하기</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Add Dive Modal */}
      {isDiveModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-3xl p-6 border border-[#2d2d3a] max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-6">기록 추가</h2>
            <form onSubmit={handleAddDive} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">종목</label>
                <select name="discipline" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500 appearance-none" required defaultValue={Discipline.STA}>
                  <option value={Discipline.STA}>STA (Static Apnea)</option>
                  <option value={Discipline.DYN}>DYN (Dynamic)</option>
                  <option value={Discipline.FIM}>FIM (Free Immersion)</option>
                  <option value={Discipline.CWT}>CWT (Constant Weight)</option>
                </select>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">시간 (MM:SS)</label>
                  <input type="text" name="time" placeholder="00:00" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
                </div>
                <div>
                  <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">거리 (m)</label>
                  <input type="number" name="distance" placeholder="0" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
                </div>
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">깊이 (m)</label>
                <input type="number" name="depth" placeholder="0" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">
                    사진/영상 {accessToken && <span className="text-blue-400 ml-1">(Google Drive Upload Active)</span>}
                </label>
                <div className="relative group">
                  <input type="file" name="media" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer z-10" disabled={isUploading} />
                  <div className="bg-[#0f0f17] border border-[#2d2d3a] border-dashed rounded-xl px-4 py-6 flex flex-col items-center gap-2 group-hover:border-purple-500 transition-colors">
                    {isUploading ? <Loader2 className="text-purple-500 animate-spin" /> : <Camera className="text-gray-500 group-hover:text-purple-500" />}
                    <span className="text-xs text-gray-500">{isUploading ? '업로드 중...' : '미디어 업로드'}</span>
                  </div>
                </div>
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">메모</label>
                <input type="text" name="note" placeholder="간단한 소감" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>

              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setIsDiveModalOpen(false)} className="flex-1 text-sm font-bold text-gray-400 py-3 rounded-xl hover:bg-[#2d2d3a]" disabled={isUploading}>취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 text-sm font-bold text-white py-3 rounded-xl hover:bg-purple-500 disabled:opacity-50" disabled={isUploading}>
                    {isUploading ? '저장 중...' : '기록 저장'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { Plus, Trophy, Calendar, MapPin, Users, ChevronLeft, Trash2, Camera, Play, Cloud, CloudOff, Loader2, ExternalLink } from 'lucide-react';
import { Discipline, DiveSession, DiveEntry, MediaFile, PersonalBest } from './types';
import { formatTime, calculateOverallPB, calculateSessionPB, fileToBase64 } from './utils';

// Constants for Google Drive
const DRIVE_FOLDER_ID = '1Kcx0f-fqKsnYzof58Gg5gMZfKaeg4e_x';
const CLIENT_ID = 'YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com'; // User needs to provide this for real functionality
const SCOPES = 'https://www.googleapis.com/auth/drive.file';

// Components
const DisciplineBadge: React.FC<{ type: Discipline }> = ({ type }) => {
  const colors: Record<Discipline, string> = {
    [Discipline.STA]: 'bg-purple-500/20 text-purple-400 border-purple-500/30',
    [Discipline.DYN]: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    [Discipline.FIM]: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    [Discipline.CWT]: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  };
  return (
    <span className={`px-2 py-0.5 rounded text-[10px] font-bold border uppercase tracking-wider ${colors[type]}`}>
      {type}
    </span>
  );
};

const PBCard: React.FC<{ pb: PersonalBest }> = ({ pb }) => {
  const subText: Record<Discipline, string> = {
    [Discipline.STA]: 'Static Apnea',
    [Discipline.DYN]: 'Dynamic',
    [Discipline.FIM]: 'Free Immersion',
    [Discipline.CWT]: 'Constant Weight',
  };

  return (
    <div className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-2xl flex flex-col justify-between hover:border-purple-500/50 transition-colors">
      <div className="flex justify-between items-start mb-4">
        <DisciplineBadge type={pb.discipline} />
        {pb.date && <span className="text-[10px] text-gray-500 font-medium">{pb.date}</span>}
      </div>
      <div>
        <div className="text-3xl font-bold text-white mb-1">{pb.value}</div>
        <div className="text-xs text-gray-400 font-medium">{subText[pb.discipline]}</div>
      </div>
    </div>
  );
};

const DiveEntryItem: React.FC<{ entry: DiveEntry; onDelete: () => void }> = ({ entry, onDelete }) => {
  return (
    <div className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-xl flex flex-col gap-3">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
          <DisciplineBadge type={entry.discipline} />
          <span className="text-xs font-semibold text-gray-400">{entry.attemptNumber}차 시도</span>
        </div>
        <button onClick={onDelete} className="p-1 text-gray-500 hover:text-red-400">
          <Trash2 size={16} />
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {entry.timeSeconds !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Time</div>
            <div className="text-lg font-semibold">{formatTime(entry.timeSeconds)}</div>
          </div>
        )}
        {entry.distanceMeters !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Distance</div>
            <div className="text-lg font-semibold">{entry.distanceMeters}m</div>
          </div>
        )}
        {entry.depthMeters !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Depth</div>
            <div className="text-lg font-semibold">{entry.depthMeters}m</div>
          </div>
        )}
      </div>

      {entry.media.length > 0 && (
        <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
          {entry.media.map(m => (
            <div key={m.id} className="relative w-16 h-16 rounded-md overflow-hidden bg-black flex-shrink-0 group">
              {m.driveFileId ? (
                <div className="w-full h-full flex flex-col items-center justify-center bg-blue-900/20 text-blue-400">
                  <Cloud size={20} />
                  <a href={m.url} target="_blank" rel="noopener noreferrer" className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                    <ExternalLink size={16} />
                  </a>
                </div>
              ) : (
                <img src={m.url} className="w-full h-full object-cover opacity-80" alt="Dive media" />
              )}
              {m.type === 'video' && !m.driveFileId && <Play size={12} className="absolute inset-0 m-auto text-white fill-white" />}
            </div>
          ))}
        </div>
      )}

      {entry.note && (
        <p className="text-xs text-gray-400 border-t border-[#2d2d3a] pt-2">{entry.note}</p>
      )}
    </div>
  );
};

export default function App() {
  const [sessions, setSessions] = useState<DiveSession[]>([]);
  const [view, setView] = useState<'dashboard' | 'session_detail'>('dashboard');
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDiveModalOpen, setIsDiveModalOpen] = useState(false);
  const [isUploading, setIsUploading] = useState(false);

  // Google Auth State
  const [accessToken, setAccessToken] = useState<string | null>(null);
  const tokenClientRef = useRef<any>(null);

  // Load from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('dive_sessions');
    if (saved) {
      try {
        setSessions(JSON.parse(saved));
      } catch (e) { console.error(e); }
    }

    // Initialize Google Identity Services
    const initGis = () => {
      // FIX: Cast window to any to access 'google' global object from GIS script
      if ((window as any).google) {
        // FIX: Cast window to any to access 'google' global object from GIS script
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: (response: any) => {
            if (response.access_token) {
              setAccessToken(response.access_token);
            }
          },
        });
      }
    };

    const checkGis = setInterval(() => {
        // FIX: Cast window to any to access 'google' global object from GIS script
        if ((window as any).google) {
            initGis();
            clearInterval(checkGis);
        }
    }, 500);

    return () => clearInterval(checkGis);
  }, []);

  // Save to localStorage
  useEffect(() => {
    localStorage.setItem('dive_sessions', JSON.stringify(sessions));
  }, [sessions]);

  const handleDriveAuth = () => {
    if (tokenClientRef.current) {
      tokenClientRef.current.requestAccessToken();
    } else {
      alert("구글 API 라이브러리를 불러오는 중입니다. 잠시 후 다시 시도해주세요.");
    }
  };

  const uploadToDrive = async (file: File, name: string): Promise<string | null> => {
    if (!accessToken) return null;

    const metadata = {
      name: name,
      parents: [DRIVE_FOLDER_ID],
    };

    const formData = new FormData();
    formData.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    formData.append('file', file);

    try {
      const response = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,webViewLink', {
        method: 'POST',
        headers: new Headers({ 'Authorization': 'Bearer ' + accessToken }),
        body: formData,
      });
      const data = await response.json();
      return data.id ? data.webViewLink : null;
    } catch (error) {
      console.error('Upload failed:', error);
      return null;
    }
  };

  const overallPB = calculateOverallPB(sessions);

  const handleCreateSession = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newSession: DiveSession = {
      id: Date.now().toString(),
      date: formData.get('date') as string,
      location: formData.get('location') as string,
      buddy: formData.get('buddy') as string,
      note: formData.get('note') as string,
      entries: [],
    };
    setSessions([newSession, ...sessions]);
    setIsModalOpen(false);
    setSelectedSessionId(newSession.id);
    setView('session_detail');
  };

  const handleAddDive = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!selectedSessionId) return;

    const formData = new FormData(e.currentTarget);
    const discipline = formData.get('discipline') as Discipline;
    const session = sessions.find(s => s.id === selectedSessionId);
    if (!session) return;

    const attemptNumber = session.entries.filter(e => e.discipline === discipline).length + 1;

    // Media processing
    const mediaFiles = formData.getAll('media') as File[];
    const processedMedia: MediaFile[] = [];

    if (mediaFiles.length > 0 && mediaFiles[0].size > 0) {
        setIsUploading(true);
        for (const f of mediaFiles) {
            if (f.size > 0) {
                // If connected to Drive, upload there. Otherwise, use Base64
                let driveUrl: string | null = null;
                const fileName = `${session.date} ${discipline}_${attemptNumber}`;

                if (accessToken) {
                    driveUrl = await uploadToDrive(f, fileName);
                }

                if (driveUrl) {
                    processedMedia.push({
                        id: Math.random().toString(36).substr(2, 9),
                        type: f.type.startsWith('video') ? 'video' : 'image',
                        url: driveUrl,
                        driveFileId: 'uploaded'
                    });
                } else {
                    const base64 = await fileToBase64(f);
                    processedMedia.push({
                        id: Math.random().toString(36).substr(2, 9),
                        type: f.type.startsWith('video') ? 'video' : 'image',
                        url: base64
                    });
                }
            }
        }
        setIsUploading(false);
    }

    const timeStr = formData.get('time') as string;
    let timeSeconds: number | undefined;
    if (timeStr) {
        const [m, s] = timeStr.split(':').map(Number);
        timeSeconds = (m || 0) * 60 + (s || 0);
    }

    const newEntry: DiveEntry = {
      id: Date.now().toString(),
      discipline,
      attemptNumber,
      timeSeconds,
      distanceMeters: formData.get('distance') ? Number(formData.get('distance')) : undefined,
      depthMeters: formData.get('depth') ? Number(formData.get('depth')) : undefined,
      media: processedMedia,
      note: formData.get('note') as string,
      timestamp: Date.now(),
    };

    setSessions(sessions.map(s => 
      s.id === selectedSessionId ? { ...s, entries: [...s.entries, newEntry] } : s
    ));
    setIsDiveModalOpen(false);
  };

  const deleteSession = (id: string) => {
    if (confirm('이 세션을 삭제하시겠습니까?')) {
      setSessions(sessions.filter(s => s.id !== id));
      setView('dashboard');
    }
  };

  const deleteEntry = (sessionId: string, entryId: string) => {
    setSessions(sessions.map(s => 
      s.id === sessionId ? { ...s, entries: s.entries.filter(e => e.id !== entryId) } : s
    ));
  };

  const currentSession = sessions.find(s => s.id === selectedSessionId);
  const sessionPBs = currentSession ? calculateSessionPB(currentSession.entries) : {};

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0f0f17] pb-20 overflow-x-hidden">
      {/* Header */}
      <header className="sticky top-0 z-20 bg-[#0f0f17]/80 backdrop-blur-md px-6 py-4 flex justify-between items-center border-b border-[#1a1a24]">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-purple-600 rounded-xl flex items-center justify-center shadow-lg shadow-purple-900/20">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-white">
              <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" />
              <circle cx="12" cy="12" r="3" />
            </svg>
          </div>
          <div>
            <h1 className="text-lg font-bold leading-tight">DiveLog</h1>
            <button 
                onClick={handleDriveAuth}
                className="flex items-center gap-1.5 text-[9px] font-bold uppercase tracking-wider transition-colors"
                style={{ color: accessToken ? '#4ade80' : '#6b7280' }}
            >
                {accessToken ? <Cloud size={10} /> : <CloudOff size={10} />}
                {accessToken ? 'Drive Synced' : 'Drive Off'}
            </button>
          </div>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-purple-600 hover:bg-purple-500 text-white font-bold py-2.5 px-5 rounded-xl flex items-center gap-2 shadow-lg shadow-purple-900/40 transition-all active:scale-95"
        >
          <Plus size={18} />
          <span className="text-sm">새 세션</span>
        </button>
      </header>

      {view === 'dashboard' ? (
        <main className="p-6 space-y-8">
          <section>
            <div className="flex items-center gap-2 mb-4">
              <Trophy size={18} className="text-yellow-500" />
              <h2 className="text-lg font-bold">Overall PB</h2>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {overallPB.map(pb => (
                <PBCard key={pb.discipline} pb={pb} />
              ))}
            </div>
          </section>

          <section>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-bold">다이브 세션</h2>
              <span className="text-xs text-gray-500 font-medium">{sessions.length} sessions</span>
            </div>

            {sessions.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-20 text-center space-y-4 opacity-50">
                <Calendar size={48} className="text-gray-700" />
                <p className="text-gray-400 font-medium">아직 기록된 세션이 없습니다</p>
              </div>
            ) : (
              <div className="space-y-4">
                {sessions.map(session => {
                  const sPBs = calculateSessionPB(session.entries);
                  return (
                    <div 
                      key={session.id} 
                      onClick={() => { setSelectedSessionId(session.id); setView('session_detail'); }}
                      className="bg-[#1a1a24] border border-[#2d2d3a] p-5 rounded-2xl cursor-pointer hover:border-purple-500/40 transition-all active:scale-[0.98]"
                    >
                      <div className="flex justify-between items-start mb-3">
                        <div>
                          <h3 className="font-bold text-lg mb-1">{session.date}</h3>
                          <div className="flex items-center gap-3 text-xs text-gray-400">
                            <span className="flex items-center gap-1"><MapPin size={12} className="text-purple-500" />{session.location}</span>
                            <span className="flex items-center gap-1"><Users size={12} className="text-purple-500" />{session.buddy}</span>
                          </div>
                        </div>
                      </div>
                      <div className="flex gap-2 flex-wrap">
                        {Object.entries(sPBs).map(([disc, val]) => (
                          <div key={disc} className="bg-[#0f0f17] border border-[#2d2d3a] px-2 py-1 rounded-lg flex items-center gap-2">
                            <span className="text-[10px] font-bold text-purple-400">{disc}</span>
                            <span className="text-xs font-bold">{val}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </section>
        </main>
      ) : (
        <main className="p-6 space-y-6">
          <div className="flex items-center justify-between">
            <button onClick={() => setView('dashboard')} className="flex items-center gap-1 text-gray-400 hover:text-white transition-colors">
              <ChevronLeft size={20} />
              <span className="text-sm font-medium">대시보드</span>
            </button>
            <button onClick={() => deleteSession(selectedSessionId!)} className="text-gray-500 hover:text-red-400">
              <Trash2 size={18} />
            </button>
          </div>

          {currentSession && (
            <>
              <div className="space-y-2">
                <h2 className="text-2xl font-bold">{currentSession.date}</h2>
                <div className="flex gap-4 text-xs text-gray-400">
                  <span className="flex items-center gap-1"><MapPin size={14} className="text-purple-500" />{currentSession.location}</span>
                  <span className="flex items-center gap-1"><Users size={14} className="text-purple-500" />{currentSession.buddy}</span>
                </div>
                {currentSession.note && <p className="text-sm text-gray-400 bg-[#1a1a24] p-3 rounded-xl">{currentSession.note}</p>}
              </div>

              <div className="grid grid-cols-2 gap-3">
                {Object.entries(sessionPBs).map(([disc, val]) => (
                  <div key={disc} className="bg-[#1a1a24] border border-[#2d2d3a] p-3 rounded-xl flex items-center justify-between">
                    <span className="text-xs font-bold text-gray-400">{disc} PB</span>
                    <span className="text-sm font-bold text-purple-400">{val}</span>
                  </div>
                ))}
              </div>

              <div className="flex items-center justify-between pt-4 border-t border-[#1a1a24]">
                <h3 className="font-bold">다이브 로그 ({currentSession.entries.length})</h3>
                <button 
                  onClick={() => setIsDiveModalOpen(true)}
                  className="bg-[#1a1a24] border border-[#2d2d3a] text-xs font-bold py-2 px-4 rounded-lg hover:bg-[#2d2d3a] transition-all flex items-center gap-1"
                >
                  <Plus size={14} /> 기록 추가
                </button>
              </div>

              <div className="space-y-4">
                {currentSession.entries.length === 0 ? (
                  <p className="text-center py-10 text-gray-500 text-sm italic">기록된 다이브가 없습니다.</p>
                ) : (
                  [...currentSession.entries].sort((a,b) => b.timestamp - a.timestamp).map(entry => (
                    <DiveEntryItem 
                        key={entry.id} 
                        entry={entry} 
                        onDelete={() => deleteEntry(selectedSessionId!, entry.id)} 
                    />
                  ))
                )}
              </div>
            </>
          )}
        </main>
      )}

      {/* New Session Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-3xl p-6 border border-[#2d2d3a]">
            <h2 className="text-xl font-bold mb-6">새 다이브 세션</h2>
            <form onSubmit={handleCreateSession} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">날짜</label>
                <input required type="date" name="date" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" defaultValue={new Date().toISOString().split('T')[0]} />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">장소</label>
                <input required type="text" name="location" placeholder="K2, 파라다이스, 올림픽수영장 등" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">버디</label>
                <input required type="text" name="buddy" placeholder="함께한 사람 이름" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">메모</label>
                <textarea name="note" rows={2} placeholder="오늘의 컨디션이나 특이사항" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500 resize-none"></textarea>
              </div>
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 text-sm font-bold text-gray-400 py-3 rounded-xl hover:bg-[#2d2d3a]">취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 text-sm font-bold text-white py-3 rounded-xl hover:bg-purple-500 shadow-lg shadow-purple-900/30">세션 시작하기</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Add Dive Modal */}
      {isDiveModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-3xl p-6 border border-[#2d2d3a] max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-6">기록 추가</h2>
            <form onSubmit={handleAddDive} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">종목</label>
                <select name="discipline" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500 appearance-none" required defaultValue={Discipline.STA}>
                  <option value={Discipline.STA}>STA (Static Apnea)</option>
                  <option value={Discipline.DYN}>DYN (Dynamic)</option>
                  <option value={Discipline.FIM}>FIM (Free Immersion)</option>
                  <option value={Discipline.CWT}>CWT (Constant Weight)</option>
                </select>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">시간 (MM:SS)</label>
                  <input type="text" name="time" placeholder="00:00" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
                </div>
                <div>
                  <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">거리 (m)</label>
                  <input type="number" name="distance" placeholder="0" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
                </div>
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">깊이 (m)</label>
                <input type="number" name="depth" placeholder="0" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">
                    사진/영상 {accessToken && <span className="text-blue-400 ml-1">(Google Drive Upload Active)</span>}
                </label>
                <div className="relative group">
                  <input type="file" name="media" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer z-10" disabled={isUploading} />
                  <div className="bg-[#0f0f17] border border-[#2d2d3a] border-dashed rounded-xl px-4 py-6 flex flex-col items-center gap-2 group-hover:border-purple-500 transition-colors">
                    {isUploading ? <Loader2 className="text-purple-500 animate-spin" /> : <Camera className="text-gray-500 group-hover:text-purple-500" />}
                    <span className="text-xs text-gray-500">{isUploading ? '업로드 중...' : '미디어 업로드'}</span>
                  </div>
                </div>
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">메모</label>
                <input type="text" name="note" placeholder="간단한 소감" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>

              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setIsDiveModalOpen(false)} className="flex-1 text-sm font-bold text-gray-400 py-3 rounded-xl hover:bg-[#2d2d3a]" disabled={isUploading}>취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 text-sm font-bold text-white py-3 rounded-xl hover:bg-purple-500 disabled:opacity-50" disabled={isUploading}>
                    {isUploading ? '저장 중...' : '기록 저장'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { Plus, Trophy, Calendar, MapPin, Users, ChevronLeft, Trash2, Camera, Play, Cloud, CloudOff, Loader2, ExternalLink } from 'lucide-react';
import { Discipline, DiveSession, DiveEntry, MediaFile, PersonalBest } from './types';
import { formatTime, calculateOverallPB, calculateSessionPB, fileToBase64 } from './utils';

// Constants for Google Drive
const DRIVE_FOLDER_ID = '1Kcx0f-fqKsnYzof58Gg5gMZfKaeg4e_x';
const CLIENT_ID = '229707401391-cfovrjr2ecse3vk4jv613pkgi3mmmn0a.apps.googleusercontent.com'; 
const SCOPES = 'https://www.googleapis.com/auth/drive.file';

// Components
const DisciplineBadge: React.FC<{ type: Discipline }> = ({ type }) => {
  const colors: Record<Discipline, string> = {
    [Discipline.STA]: 'bg-purple-500/20 text-purple-400 border-purple-500/30',
    [Discipline.DYN]: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    [Discipline.FIM]: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    [Discipline.CWT]: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  };
  return (
    <span className={`px-2 py-0.5 rounded text-[10px] font-bold border uppercase tracking-wider ${colors[type]}`}>
      {type}
    </span>
  );
};

const PBCard: React.FC<{ pb: PersonalBest }> = ({ pb }) => {
  const subText: Record<Discipline, string> = {
    [Discipline.STA]: 'Static Apnea',
    [Discipline.DYN]: 'Dynamic',
    [Discipline.FIM]: 'Free Immersion',
    [Discipline.CWT]: 'Constant Weight',
  };

  return (
    <div className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-2xl flex flex-col justify-between hover:border-purple-500/50 transition-colors">
      <div className="flex justify-between items-start mb-4">
        <DisciplineBadge type={pb.discipline} />
        {pb.date && <span className="text-[10px] text-gray-500 font-medium">{pb.date}</span>}
      </div>
      <div>
        <div className="text-3xl font-bold text-white mb-1">{pb.value}</div>
        <div className="text-xs text-gray-400 font-medium">{subText[pb.discipline]}</div>
      </div>
    </div>
  );
};

const DiveEntryItem: React.FC<{ entry: DiveEntry; onDelete: () => void }> = ({ entry, onDelete }) => {
  return (
    <div className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-xl flex flex-col gap-3">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
          <DisciplineBadge type={entry.discipline} />
          <span className="text-xs font-semibold text-gray-400">{entry.attemptNumber}차 시도</span>
        </div>
        <button onClick={onDelete} className="p-1 text-gray-500 hover:text-red-400">
          <Trash2 size={16} />
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {entry.timeSeconds !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Time</div>
            <div className="text-lg font-semibold">{formatTime(entry.timeSeconds)}</div>
          </div>
        )}
        {entry.distanceMeters !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Distance</div>
            <div className="text-lg font-semibold">{entry.distanceMeters}m</div>
          </div>
        )}
        {entry.depthMeters !== undefined && (
          <div>
            <div className="text-[10px] text-gray-500 uppercase font-bold">Depth</div>
            <div className="text-lg font-semibold">{entry.depthMeters}m</div>
          </div>
        )}
      </div>

      {entry.media.length > 0 && (
        <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
          {entry.media.map(m => (
            <div key={m.id} className="relative w-16 h-16 rounded-md overflow-hidden bg-black flex-shrink-0 group">
              {m.driveFileId ? (
                <div className="w-full h-full flex flex-col items-center justify-center bg-blue-900/20 text-blue-400">
                  <Cloud size={20} />
                  <a href={m.url} target="_blank" rel="noopener noreferrer" className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                    <ExternalLink size={16} />
                  </a>
                </div>
              ) : (
                <img src={m.url} className="w-full h-full object-cover opacity-80" alt="Dive media" />
              )}
              {m.type === 'video' && !m.driveFileId && <Play size={12} className="absolute inset-0 m-auto text-white fill-white" />}
            </div>
          ))}
        </div>
      )}

      {entry.note && (
        <p className="text-xs text-gray-400 border-t border-[#2d2d3a] pt-2">{entry.note}</p>
      )}
    </div>
  );
};

export default function App() {
  const [sessions, setSessions] = useState<DiveSession[]>([]);
  const [view, setView] = useState<'dashboard' | 'session_detail'>('dashboard');
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDiveModalOpen, setIsDiveModalOpen] = useState(false);
  const [isUploading, setIsUploading] = useState(false);

  // Google Auth State
  const [accessToken, setAccessToken] = useState<string | null>(null);
  const tokenClientRef = useRef<any>(null);

  // Load from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('dive_sessions');
    if (saved) {
      try {
        setSessions(JSON.parse(saved));
      } catch (e) { console.error(e); }
    }

    // Initialize Google Identity Services
    const initGis = () => {
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: (response: any) => {
            if (response.access_token) {
              setAccessToken(response.access_token);
            }
          },
        });
      }
    };

    const checkGis = setInterval(() => {
        if ((window as any).google) {
            initGis();
            clearInterval(checkGis);
        }
    }, 500);

    return () => clearInterval(checkGis);
  }, []);

  // Save to localStorage
  useEffect(() => {
    localStorage.setItem('dive_sessions', JSON.stringify(sessions));
  }, [sessions]);

  const handleDriveAuth = () => {
    if (tokenClientRef.current) {
      tokenClientRef.current.requestAccessToken();
    } else {
      alert("구글 API 라이브러리를 불러오는 중입니다. 잠시 후 다시 시도해주세요.");
    }
  };

  const uploadToDrive = async (file: File, name: string): Promise<string | null> => {
    if (!accessToken) return null;

    const metadata = {
      name: name,
      parents: [DRIVE_FOLDER_ID],
    };

    const formData = new FormData();
    formData.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    formData.append('file', file);

    try {
      const response = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,webViewLink', {
        method: 'POST',
        headers: new Headers({ 'Authorization': 'Bearer ' + accessToken }),
        body: formData,
      });
      const data = await response.json();
      return data.id ? data.webViewLink : null;
    } catch (error) {
      console.error('Upload failed:', error);
      return null;
    }
  };

  const overallPB = calculateOverallPB(sessions);

  const handleCreateSession = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newSession: DiveSession = {
      id: Date.now().toString(),
      date: formData.get('date') as string,
      location: formData.get('location') as string,
      buddy: formData.get('buddy') as string,
      note: formData.get('note') as string,
      entries: [],
    };
    setSessions([newSession, ...sessions]);
    setIsModalOpen(false);
    setSelectedSessionId(newSession.id);
    setView('session_detail');
  };

  const handleAddDive = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!selectedSessionId) return;

    const formData = new FormData(e.currentTarget);
    const discipline = formData.get('discipline') as Discipline;
    const session = sessions.find(s => s.id === selectedSessionId);
    if (!session) return;

    const attemptNumber = session.entries.filter(e => e.discipline === discipline).length + 1;

    // Media processing
    const mediaFiles = formData.getAll('media') as File[];
    const processedMedia: MediaFile[] = [];

    if (mediaFiles.length > 0 && mediaFiles[0].size > 0) {
        setIsUploading(true);
        for (const f of mediaFiles) {
            if (f.size > 0) {
                // If connected to Drive, upload there. Otherwise, use Base64
                let driveUrl: string | null = null;
                const fileName = `${session.date} ${discipline}_${attemptNumber}`;

                if (accessToken) {
                    driveUrl = await uploadToDrive(f, fileName);
                }

                if (driveUrl) {
                    processedMedia.push({
                        id: Math.random().toString(36).substr(2, 9),
                        type: f.type.startsWith('video') ? 'video' : 'image',
                        url: driveUrl,
                        driveFileId: 'uploaded'
                    });
                } else {
                    const base64 = await fileToBase64(f);
                    processedMedia.push({
                        id: Math.random().toString(36).substr(2, 9),
                        type: f.type.startsWith('video') ? 'video' : 'image',
                        url: base64
                    });
                }
            }
        }
        setIsUploading(false);
    }

    const timeStr = formData.get('time') as string;
    let timeSeconds: number | undefined;
    if (timeStr) {
        const [m, s] = timeStr.split(':').map(Number);
        timeSeconds = (m || 0) * 60 + (s || 0);
    }

    const newEntry: DiveEntry = {
      id: Date.now().toString(),
      discipline,
      attemptNumber,
      timeSeconds,
      distanceMeters: formData.get('distance') ? Number(formData.get('distance')) : undefined,
      depthMeters: formData.get('depth') ? Number(formData.get('depth')) : undefined,
      media: processedMedia,
      note: formData.get('note') as string,
      timestamp: Date.now(),
    };

    setSessions(sessions.map(s => 
      s.id === selectedSessionId ? { ...s, entries: [...s.entries, newEntry] } : s
    ));
    setIsDiveModalOpen(false);
  };

  const deleteSession = (id: string) => {
    if (confirm('이 세션을 삭제하시겠습니까?')) {
      setSessions(sessions.filter(s => s.id !== id));
      setView('dashboard');
    }
  };

  const deleteEntry = (sessionId: string, entryId: string) => {
    setSessions(sessions.map(s => 
      s.id === sessionId ? { ...s, entries: s.entries.filter(e => e.id !== entryId) } : s
    ));
  };

  const currentSession = sessions.find(s => s.id === selectedSessionId);
  const sessionPBs = currentSession ? calculateSessionPB(currentSession.entries) : {};

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0f0f17] pb-20 overflow-x-hidden">
      {/* Header */}
      <header className="sticky top-0 z-20 bg-[#0f0f17]/80 backdrop-blur-md px-6 py-4 flex justify-between items-center border-b border-[#1a1a24]">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-purple-600 rounded-xl flex items-center justify-center shadow-lg shadow-purple-900/20">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-white">
              <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" />
              <circle cx="12" cy="12" r="3" />
            </svg>
          </div>
          <div>
            <h1 className="text-lg font-bold leading-tight">DiveLog</h1>
            <button 
                onClick={handleDriveAuth}
                className="flex items-center gap-1.5 text-[9px] font-bold uppercase tracking-wider transition-colors"
                style={{ color: accessToken ? '#4ade80' : '#6b7280' }}
            >
                {accessToken ? <Cloud size={10} /> : <CloudOff size={10} />}
                {accessToken ? 'Drive Synced' : 'Drive Off'}
            </button>
          </div>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-purple-600 hover:bg-purple-500 text-white font-bold py-2.5 px-5 rounded-xl flex items-center gap-2 shadow-lg shadow-purple-900/40 transition-all active:scale-95"
        >
          <Plus size={18} />
          <span className="text-sm">새 세션</span>
        </button>
      </header>

      {view === 'dashboard' ? (
        <main className="p-6 space-y-8">
          <section>
            <div className="flex items-center gap-2 mb-4">
              <Trophy size={18} className="text-yellow-500" />
              <h2 className="text-lg font-bold">Overall PB</h2>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {overallPB.map(pb => (
                <PBCard key={pb.discipline} pb={pb} />
              ))}
            </div>
          </section>

          <section>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-bold">다이브 세션</h2>
              <span className="text-xs text-gray-500 font-medium">{sessions.length} sessions</span>
            </div>

            {sessions.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-20 text-center space-y-4 opacity-50">
                <Calendar size={48} className="text-gray-700" />
                <p className="text-gray-400 font-medium">아직 기록된 세션이 없습니다</p>
              </div>
            ) : (
              <div className="space-y-4">
                {sessions.map(session => {
                  const sPBs = calculateSessionPB(session.entries);
                  return (
                    <div 
                      key={session.id} 
                      onClick={() => { setSelectedSessionId(session.id); setView('session_detail'); }}
                      className="bg-[#1a1a24] border border-[#2d2d3a] p-5 rounded-2xl cursor-pointer hover:border-purple-500/40 transition-all active:scale-[0.98]"
                    >
                      <div className="flex justify-between items-start mb-3">
                        <div>
                          <h3 className="font-bold text-lg mb-1">{session.date}</h3>
                          <div className="flex items-center gap-3 text-xs text-gray-400">
                            <span className="flex items-center gap-1"><MapPin size={12} className="text-purple-500" />{session.location}</span>
                            <span className="flex items-center gap-1"><Users size={12} className="text-purple-500" />{session.buddy}</span>
                          </div>
                        </div>
                      </div>
                      <div className="flex gap-2 flex-wrap">
                        {Object.entries(sPBs).map(([disc, val]) => (
                          <div key={disc} className="bg-[#0f0f17] border border-[#2d2d3a] px-2 py-1 rounded-lg flex items-center gap-2">
                            <span className="text-[10px] font-bold text-purple-400">{disc}</span>
                            <span className="text-xs font-bold">{val}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </section>
        </main>
      ) : (
        <main className="p-6 space-y-6">
          <div className="flex items-center justify-between">
            <button onClick={() => setView('dashboard')} className="flex items-center gap-1 text-gray-400 hover:text-white transition-colors">
              <ChevronLeft size={20} />
              <span className="text-sm font-medium">대시보드</span>
            </button>
            <button onClick={() => deleteSession(selectedSessionId!)} className="text-gray-500 hover:text-red-400">
              <Trash2 size={18} />
            </button>
          </div>

          {currentSession && (
            <>
              <div className="space-y-2">
                <h2 className="text-2xl font-bold">{currentSession.date}</h2>
                <div className="flex gap-4 text-xs text-gray-400">
                  <span className="flex items-center gap-1"><MapPin size={14} className="text-purple-500" />{currentSession.location}</span>
                  <span className="flex items-center gap-1"><Users size={14} className="text-purple-500" />{currentSession.buddy}</span>
                </div>
                {currentSession.note && <p className="text-sm text-gray-400 bg-[#1a1a24] p-3 rounded-xl">{currentSession.note}</p>}
              </div>

              <div className="grid grid-cols-2 gap-3">
                {Object.entries(sessionPBs).map(([disc, val]) => (
                  <div key={disc} className="bg-[#1a1a24] border border-[#2d2d3a] p-3 rounded-xl flex items-center justify-between">
                    <span className="text-xs font-bold text-gray-400">{disc} PB</span>
                    <span className="text-sm font-bold text-purple-400">{val}</span>
                  </div>
                ))}
              </div>

              <div className="flex items-center justify-between pt-4 border-t border-[#1a1a24]">
                <h3 className="font-bold">다이브 로그 ({currentSession.entries.length})</h3>
                <button 
                  onClick={() => setIsDiveModalOpen(true)}
                  className="bg-[#1a1a24] border border-[#2d2d3a] text-xs font-bold py-2 px-4 rounded-lg hover:bg-[#2d2d3a] transition-all flex items-center gap-1"
                >
                  <Plus size={14} /> 기록 추가
                </button>
              </div>

              <div className="space-y-4">
                {currentSession.entries.length === 0 ? (
                  <p className="text-center py-10 text-gray-500 text-sm italic">기록된 다이브가 없습니다.</p>
                ) : (
                  [...currentSession.entries].sort((a,b) => b.timestamp - a.timestamp).map(entry => (
                    <DiveEntryItem 
                        key={entry.id} 
                        entry={entry} 
                        onDelete={() => deleteEntry(selectedSessionId!, entry.id)} 
                    />
                  ))
                )}
              </div>
            </>
          )}
        </main>
      )}

      {/* New Session Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-3xl p-6 border border-[#2d2d3a]">
            <h2 className="text-xl font-bold mb-6">새 다이브 세션</h2>
            <form onSubmit={handleCreateSession} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">날짜</label>
                <input required type="date" name="date" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" defaultValue={new Date().toISOString().split('T')[0]} />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">장소</label>
                <input required type="text" name="location" placeholder="K2, 파라다이스, 올림픽수영장 등" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">버디</label>
                <input required type="text" name="buddy" placeholder="함께한 사람 이름" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">메모</label>
                <textarea name="note" rows={2} placeholder="오늘의 컨디션이나 특이사항" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500 resize-none"></textarea>
              </div>
              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 text-sm font-bold text-gray-400 py-3 rounded-xl hover:bg-[#2d2d3a]">취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 text-sm font-bold text-white py-3 rounded-xl hover:bg-purple-500 shadow-lg shadow-purple-900/30">세션 시작하기</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Add Dive Modal */}
      {isDiveModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-3xl p-6 border border-[#2d2d3a] max-h-[90vh] overflow-y-auto">
            <h2 className="text-xl font-bold mb-6">기록 추가</h2>
            <form onSubmit={handleAddDive} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">종목</label>
                <select name="discipline" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500 appearance-none" required defaultValue={Discipline.STA}>
                  <option value={Discipline.STA}>STA (Static Apnea)</option>
                  <option value={Discipline.DYN}>DYN (Dynamic)</option>
                  <option value={Discipline.FIM}>FIM (Free Immersion)</option>
                  <option value={Discipline.CWT}>CWT (Constant Weight)</option>
                </select>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">시간 (MM:SS)</label>
                  <input type="text" name="time" placeholder="00:00" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
                </div>
                <div>
                  <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">거리 (m)</label>
                  <input type="number" name="distance" placeholder="0" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
                </div>
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">깊이 (m)</label>
                <input type="number" name="depth" placeholder="0" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">
                    사진/영상 {accessToken && <span className="text-blue-400 ml-1">(Google Drive Upload Active)</span>}
                </label>
                <div className="relative group">
                  <input type="file" name="media" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer z-10" disabled={isUploading} />
                  <div className="bg-[#0f0f17] border border-[#2d2d3a] border-dashed rounded-xl px-4 py-6 flex flex-col items-center gap-2 group-hover:border-purple-500 transition-colors">
                    {isUploading ? <Loader2 className="text-purple-500 animate-spin" /> : <Camera className="text-gray-500 group-hover:text-purple-500" />}
                    <span className="text-xs text-gray-500">{isUploading ? '업로드 중...' : '미디어 업로드'}</span>
                  </div>
                </div>
              </div>

              <div>
                <label className="text-[10px] uppercase font-bold text-gray-500 block mb-1.5 ml-1">메모</label>
                <input type="text" name="note" placeholder="간단한 소감" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-xl px-4 py-3 text-sm focus:outline-none focus:border-purple-500" />
              </div>

              <div className="flex gap-3 pt-2">
                <button type="button" onClick={() => setIsDiveModalOpen(false)} className="flex-1 text-sm font-bold text-gray-400 py-3 rounded-xl hover:bg-[#2d2d3a]" disabled={isUploading}>취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 text-sm font-bold text-white py-3 rounded-xl hover:bg-purple-500 disabled:opacity-50" disabled={isUploading}>
                    {isUploading ? '저장 중...' : '기록 저장'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export enum Discipline {
  STA = 'STA',
  DYN = 'DYN',
  FIM = 'FIM',
  CWT = 'CWT'
}

export interface User {
  id: string;
  name: string;
  password?: string;
  avatar?: string;
}

export interface MediaFile {
  id: string;
  type: 'image' | 'video';
  url: string; // Base64 (local) or Google Drive URL
  driveFileId?: string;
  thumbnailUrl?: string; // Google Drive Thumbnail Link
}

export interface DiveEntry {
  id: string;
  discipline: Discipline;
  attemptNumber: number;
  timeSeconds?: number;
  distanceMeters?: number;
  depthMeters?: number;
  media: MediaFile[];
  note?: string;
  timestamp: number;
}

export interface DiveSession {
  id: string;
  ownerId: string;
  ownerName: string;
  date: string;
  location: string;
  buddy: string;
  note: string;
  entries: DiveEntry[];
}

export interface PersonalBest {
  discipline: Discipline;
  value: string;
  date?: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Trophy, Calendar, MapPin, Users, ChevronLeft, Trash2, Camera, 
  Play, Cloud, CloudOff, Loader2, ExternalLink, Globe, User as UserIcon, 
  LogOut, Edit2, Check, X, Search
} from 'lucide-react';
import { Discipline, DiveSession, DiveEntry, MediaFile, PersonalBest, User } from './types';
import { formatTime, calculateOverallPB, calculateSessionPB, fileToBase64 } from './utils';

const DRIVE_FOLDER_ID = '1Kcx0f-fqKsnYzof58Gg5gMZfKaeg4e_x';
const CLIENT_ID = '229707401391-cfovrjr2ecse3vk4jv613pkgi3mmmn0a.apps.googleusercontent.com'; 
const SCOPES = 'https://www.googleapis.com/auth/drive.file';

// --- Sub-components ---

const DisciplineBadge: React.FC<{ type: Discipline }> = ({ type }) => {
  const colors: Record<Discipline, string> = {
    [Discipline.STA]: 'bg-purple-500/20 text-purple-400 border-purple-500/30',
    [Discipline.DYN]: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
    [Discipline.FIM]: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
    [Discipline.CWT]: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  };
  return (
    <span className={`px-2 py-0.5 rounded text-[10px] font-bold border uppercase tracking-wider ${colors[type]}`}>
      {type}
    </span>
  );
};

const MediaThumbnail: React.FC<{ media: MediaFile }> = ({ media }) => {
  return (
    <div className="relative w-20 h-20 rounded-xl overflow-hidden bg-[#1a1a24] border border-[#2d2d3a] flex-shrink-0 group">
      {media.thumbnailUrl || !media.driveFileId ? (
        <img src={media.thumbnailUrl || media.url} className="w-full h-full object-cover" alt="Dive media" />
      ) : (
        <div className="w-full h-full flex flex-col items-center justify-center text-blue-400 bg-blue-900/10">
          <Cloud size={20} />
          <span className="text-[8px] mt-1 font-bold">DRIVE</span>
        </div>
      )}
      {media.type === 'video' && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/20">
          <Play size={16} className="text-white fill-white" />
        </div>
      )}
      <a 
        href={media.url} 
        target="_blank" 
        rel="noopener noreferrer" 
        className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity"
      >
        <ExternalLink size={14} className="text-white" />
      </a>
    </div>
  );
};

export default function App() {
  // --- States ---
  const [activeTab, setActiveTab] = useState<'home' | 'social' | 'profile'>('home');
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [sessions, setSessions] = useState<DiveSession[]>([]);
  const [view, setView] = useState<'dashboard' | 'session_detail'>('dashboard');
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);

  // Modals
  const [isAuthModal, setIsAuthModal] = useState(false);
  const [isNewSessionModal, setIsNewSessionModal] = useState(false);
  const [isDiveModal, setIsDiveModal] = useState<{open: boolean, entry?: DiveEntry | null}>({open: false, entry: null});

  // System States
  const [isUploading, setIsUploading] = useState(false);
  const [accessToken, setAccessToken] = useState<string | null>(null);
  const tokenClientRef = useRef<any>(null);

  // --- Initial Load ---
  useEffect(() => {
    const savedSessions = localStorage.getItem('dive_sessions_v2');
    const savedUsers = localStorage.getItem('dive_users_v2');
    const savedUser = localStorage.getItem('current_user_v2');

    if (savedSessions) setSessions(JSON.parse(savedSessions));
    if (savedUsers) setUsers(JSON.parse(savedUsers));
    if (savedUser) setCurrentUser(JSON.parse(savedUser));

    // GIS Init
    const initGis = () => {
      if ((window as any).google) {
        tokenClientRef.current = (window as any).google.accounts.oauth2.initTokenClient({
          client_id: CLIENT_ID,
          scope: SCOPES,
          callback: (response: any) => {
            if (response.access_token) setAccessToken(response.access_token);
          },
        });
      }
    };
    const timer = setInterval(() => {
      if ((window as any).google) { initGis(); clearInterval(timer); }
    }, 500);
    return () => clearInterval(timer);
  }, []);

  // --- Persistence ---
  useEffect(() => { localStorage.setItem('dive_sessions_v2', JSON.stringify(sessions)); }, [sessions]);
  useEffect(() => { localStorage.setItem('dive_users_v2', JSON.stringify(users)); }, [users]);
  useEffect(() => { 
    if (currentUser) localStorage.setItem('current_user_v2', JSON.stringify(currentUser));
    else localStorage.removeItem('current_user_v2');
  }, [currentUser]);

  // --- Auth Handlers ---
  const handleAuth = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const name = formData.get('name') as string;
    const pass = formData.get('password') as string;
    const isLogin = (e.nativeEvent as any).submitter.name === 'login';

    if (isLogin) {
      const user = users.find(u => u.name === name && u.password === pass);
      if (user) { setCurrentUser(user); setIsAuthModal(false); }
      else alert('사용자 정보를 찾을 수 없습니다.');
    } else {
      if (users.find(u => u.name === name)) { alert('이미 존재하는 이름입니다.'); return; }
      const newUser = { id: Date.now().toString(), name, password: pass };
      setUsers([...users, newUser]);
      setCurrentUser(newUser);
      setIsAuthModal(false);
    }
  };

  const handleLogout = () => { setCurrentUser(null); setAccessToken(null); setView('dashboard'); setActiveTab('home'); };

  const handleDriveAuth = () => {
    if (tokenClientRef.current) tokenClientRef.current.requestAccessToken();
    else alert("API 로딩 중...");
  };

  // --- Google Drive Logic ---
  const uploadToDrive = async (file: File, name: string): Promise<{url: string, thumb?: string} | null> => {
    if (!accessToken) return null;
    const metadata = { name, parents: [DRIVE_FOLDER_ID] };
    const formData = new FormData();
    formData.append('metadata', new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    formData.append('file', file);

    try {
      const res = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,webViewLink,thumbnailLink', {
        method: 'POST',
        headers: { 'Authorization': 'Bearer ' + accessToken },
        body: formData,
      });
      const data = await res.json();
      return { url: data.webViewLink, thumb: data.thumbnailLink };
    } catch (e) { console.error(e); return null; }
  };

  // --- Session & Dive Handlers ---
  const handleCreateSession = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!currentUser) { setIsAuthModal(true); return; }
    const formData = new FormData(e.currentTarget);
    const newSession: DiveSession = {
      id: Date.now().toString(),
      ownerId: currentUser.id,
      ownerName: currentUser.name,
      date: formData.get('date') as string,
      location: formData.get('location') as string,
      buddy: formData.get('buddy') as string,
      note: formData.get('note') as string,
      entries: [],
    };
    setSessions([newSession, ...sessions]);
    setIsNewSessionModal(false);
    setSelectedSessionId(newSession.id);
    setView('session_detail');
  };

  const handleAddOrUpdateDive = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const discipline = formData.get('discipline') as Discipline;
    const session = sessions.find(s => s.id === selectedSessionId);
    if (!session) return;

    setIsUploading(true);
    const mediaFiles = formData.getAll('media') as File[];
    const processedMedia: MediaFile[] = [];

    // Edit case: keep old media if not deleting
    if (isDiveModal.entry) {
      processedMedia.push(...isDiveModal.entry.media);
    }

    for (const f of mediaFiles) {
      if (f.size > 0) {
        const fileName = `${session.date} ${discipline}_${isDiveModal.entry ? isDiveModal.entry.attemptNumber : (session.entries.length + 1)}`;
        const driveRes = await uploadToDrive(f, fileName);
        if (driveRes) {
          processedMedia.push({
            id: Math.random().toString(36).substr(2, 9),
            type: f.type.startsWith('video') ? 'video' : 'image',
            url: driveRes.url,
            driveFileId: 'drive',
            thumbnailUrl: driveRes.thumb
          });
        } else {
          const b64 = await fileToBase64(f);
          processedMedia.push({
            id: Math.random().toString(36).substr(2, 9),
            type: f.type.startsWith('video') ? 'video' : 'image',
            url: b64
          });
        }
      }
    }

    const timeStr = formData.get('time') as string;
    let timeSeconds: number | undefined;
    if (timeStr) {
      const [m, s] = timeStr.split(':').map(Number);
      timeSeconds = (m || 0) * 60 + (s || 0);
    }

    const newDive: DiveEntry = {
      id: isDiveModal.entry?.id || Date.now().toString(),
      discipline,
      attemptNumber: isDiveModal.entry?.attemptNumber || session.entries.filter(e => e.discipline === discipline).length + 1,
      timeSeconds,
      distanceMeters: formData.get('distance') ? Number(formData.get('distance')) : undefined,
      depthMeters: formData.get('depth') ? Number(formData.get('depth')) : undefined,
      media: processedMedia,
      note: formData.get('note') as string,
      timestamp: isDiveModal.entry?.timestamp || Date.now(),
    };

    setSessions(sessions.map(s => {
      if (s.id !== selectedSessionId) return s;
      const entries = isDiveModal.entry 
        ? s.entries.map(e => e.id === isDiveModal.entry?.id ? newDive : e)
        : [...s.entries, newDive];
      return { ...s, entries };
    }));

    setIsUploading(false);
    setIsDiveModal({open: false, entry: null});
  };

  // --- Filtering ---
  const mySessions = sessions.filter(s => s.ownerId === currentUser?.id);
  const currentSession = sessions.find(s => s.id === selectedSessionId);
  const overallPB = calculateOverallPB(mySessions);
  const sessionPBs = currentSession ? calculateSessionPB(currentSession.entries) : {};

  // --- UI Views ---
  const renderAuth = () => (
    <div className="flex flex-col items-center justify-center min-h-[60vh] p-8 text-center">
      <div className="w-16 h-16 bg-purple-600 rounded-2xl flex items-center justify-center shadow-xl shadow-purple-900/30 mb-6">
        <UserIcon size={32} className="text-white" />
      </div>
      <h2 className="text-2xl font-bold mb-2">프리다이버 로그인</h2>
      <p className="text-gray-400 text-sm mb-8">기록을 안전하게 보관하고<br/>다른 다이버들과 공유해보세요!</p>

      <form onSubmit={handleAuth} className="w-full space-y-4">
        <input required name="name" type="text" placeholder="이름" className="w-full bg-[#1a1a24] border border-[#2d2d3a] rounded-xl px-4 py-4 focus:border-purple-500 outline-none" />
        <input required name="password" type="password" placeholder="비밀번호" className="w-full bg-[#1a1a24] border border-[#2d2d3a] rounded-xl px-4 py-4 focus:border-purple-500 outline-none" />
        <div className="grid grid-cols-2 gap-3 pt-4">
          <button type="submit" name="login" className="bg-[#2d2d3a] text-white font-bold py-4 rounded-xl hover:bg-[#3d3d4a]">로그인</button>
          <button type="submit" name="join" className="bg-purple-600 text-white font-bold py-4 rounded-xl hover:bg-purple-500 shadow-lg shadow-purple-900/40">회원가입</button>
        </div>
      </form>
    </div>
  );

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0f0f17] pb-24">
      {/* Header */}
      <header className="sticky top-0 z-30 bg-[#0f0f17]/90 backdrop-blur-lg border-b border-[#1a1a24] px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 bg-purple-600 rounded-xl flex items-center justify-center shadow-lg shadow-purple-900/20">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" className="text-white"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z" /><circle cx="12" cy="12" r="3" /></svg>
          </div>
          <div>
            <h1 className="text-md font-bold leading-none mb-1">DiveLog</h1>
            {currentUser && (
              <button onClick={handleDriveAuth} className={`flex items-center gap-1 text-[8px] font-black tracking-tighter uppercase ${accessToken ? 'text-green-400' : 'text-gray-600'}`}>
                {accessToken ? <Cloud size={8} /> : <CloudOff size={8} />} {accessToken ? 'Connected' : 'Sync Drive'}
              </button>
            )}
          </div>
        </div>
        {currentUser ? (
          <button onClick={() => setIsNewSessionModal(true)} className="w-9 h-9 bg-[#1a1a24] text-white rounded-xl flex items-center justify-center hover:bg-purple-600 transition-colors">
            <Plus size={20} />
          </button>
        ) : (
          <button onClick={() => setIsAuthModal(true)} className="text-xs font-bold text-purple-400 border border-purple-500/30 px-3 py-1.5 rounded-lg">로그인</button>
        )}
      </header>

      {/* Main Content */}
      <div className="p-6">
        {!currentUser && activeTab !== 'social' ? renderAuth() : (
          <>
            {view === 'dashboard' ? (
              <div className="space-y-8 animate-in fade-in duration-500">
                {activeTab === 'home' ? (
                  <>
                    <section>
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-2">
                          <Trophy size={18} className="text-yellow-500" />
                          <h2 className="text-lg font-bold">나의 역대 PB</h2>
                        </div>
                      </div>
                      <div className="grid grid-cols-2 gap-3">
                        {overallPB.map(pb => (
                          <div key={pb.discipline} className="bg-[#1a1a24] border border-[#2d2d3a] p-4 rounded-2xl">
                            <DisciplineBadge type={pb.discipline} />
                            <div className="text-2xl font-black mt-3">{pb.value}</div>
                            <div className="text-[10px] text-gray-500 font-medium">{pb.date || '기록 없음'}</div>
                          </div>
                        ))}
                      </div>
                    </section>

                    <section>
                      <h2 className="text-lg font-bold mb-4">내 다이빙 세션</h2>
                      <div className="space-y-4">
                        {mySessions.length === 0 ? (
                          <div className="text-center py-20 bg-[#1a1a24]/50 rounded-3xl border border-dashed border-[#2d2d3a] text-gray-600 text-sm">기록된 세션이 없습니다.</div>
                        ) : mySessions.map(s => (
                          <div key={s.id} onClick={() => { setSelectedSessionId(s.id); setView('session_detail'); }} className="bg-[#1a1a24] border border-[#2d2d3a] p-5 rounded-2xl group hover:border-purple-500/50 transition-all cursor-pointer">
                            <div className="flex justify-between mb-3">
                              <span className="text-xs font-bold text-purple-500">{s.date}</span>
                              <div className="flex items-center gap-1 text-[10px] text-gray-500"><MapPin size={10} />{s.location}</div>
                            </div>
                            <div className="flex gap-2 mb-3">
                              {Object.entries(calculateSessionPB(s.entries)).map(([d, v]) => (
                                <div key={d} className="bg-[#0f0f17] px-2 py-1 rounded text-[10px] font-bold border border-[#2d2d3a]">
                                  <span className="text-purple-400 mr-1">{d}</span>{v}
                                </div>
                              ))}
                            </div>
                            <div className="text-xs text-gray-400 line-clamp-1 italic">"{s.note || '메모 없음'}"</div>
                          </div>
                        ))}
                      </div>
                    </section>
                  </>
                ) : activeTab === 'social' ? (
                  <section>
                    <div className="flex items-center gap-2 mb-6">
                      <Globe size={18} className="text-blue-500" />
                      <h2 className="text-lg font-bold">모든 다이버의 소식</h2>
                    </div>
                    <div className="space-y-6">
                      {sessions.map(s => (
                        <div key={s.id} className="bg-[#1a1a24] rounded-3xl overflow-hidden border border-[#2d2d3a]">
                          <div className="p-4 flex items-center gap-3 bg-[#23232f]/50">
                            <div className="w-10 h-10 bg-gradient-to-tr from-purple-600 to-blue-500 rounded-full flex items-center justify-center text-xs font-bold text-white uppercase">
                              {s.ownerName.charAt(0)}
                            </div>
                            <div>
                              <div className="text-sm font-bold">{s.ownerName} <span className="text-gray-500 font-normal text-xs">님이 다이빙을 다녀왔어요!</span></div>
                              <div className="text-[10px] text-gray-500">{s.date} @ {s.location}</div>
                            </div>
                          </div>
                          <div className="p-5">
