              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-600 uppercase ml-1 tracking-widest">Discipline</label>
                <div className="grid grid-cols-4 gap-2">
                  {Object.values(Discipline).map(d => (
                    <button key={d} type="button" onClick={() => setSelectedDiscipline(d)} className={`py-3 rounded-xl text-[10px] font-black border transition-all ${selectedDiscipline === d ? 'bg-purple-600 border-purple-500 text-white' : 'bg-[#0f0f17] border-[#2d2d3a] text-gray-500'}`}>
                      {d}
                    </button>
                  ))}
                  <input type="hidden" name="discipline" value={selectedDiscipline} />
                </div>
              </div>

              {selectedDiscipline !== Discipline.DYN && (
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-600 uppercase ml-1 flex items-center gap-1 tracking-widest"><Clock size={10}/> Time (MMSS)</label>
                  <input 
                    type="number" 
                    placeholder="예: 0130, 52" 
                    value={timeValue}
                    onChange={(e) => setTimeValue(e.target.value)}
                    className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-2xl px-5 py-4 text-lg font-black outline-none focus:border-purple-500" 
                  />
                  <div className="text-[10px] text-purple-400 font-black ml-1 uppercase">ESTIMATED: {formatTime(parseSmartTime(timeValue))}</div>
                </div>
              )}

              {selectedDiscipline === Discipline.DYN && (
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-600 uppercase ml-1 tracking-widest">Distance (m)</label>
                  <input type="number" name="distance" placeholder="0" defaultValue={isDiveModal.entry?.distanceMeters || ''} className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-2xl px-5 py-4 text-lg font-black outline-none focus:border-purple-500" />
                </div>
              )}

              {(selectedDiscipline === Discipline.FIM || selectedDiscipline === Discipline.CWT) && (
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-600 uppercase ml-1 tracking-widest">Depth (m)</label>
                  <input type="number" name="depth" placeholder="0" defaultValue={isDiveModal.entry?.depthMeters || ''} className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-2xl px-5 py-4 text-lg font-black outline-none focus:border-purple-500" />
                </div>
              )}

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-600 uppercase ml-1 tracking-widest">Media</label>
                <div className="relative overflow-hidden bg-[#0f0f17] border border-[#2d2d3a] border-dashed rounded-2xl p-6 text-center hover:border-purple-500 transition-colors">
                  <input type="file" name="media" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer" />
                  <Camera className="mx-auto text-gray-600 mb-1" size={24}/>
                  <div className="text-[9px] text-gray-600 font-black uppercase">Click to add photos/videos</div>
                </div>
              </div>
              <textarea name="note" placeholder="오늘의 짧은 기록" defaultValue={isDiveModal.entry?.note || ''} className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-2xl px-5 py-4 text-sm outline-none resize-none focus:border-purple-500"></textarea>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsDiveModal({open: false, entry: null})} className="flex-1 font-bold text-gray-500 py-4" disabled={isUploading}>취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 font-black text-white py-4 rounded-3xl disabled:opacity-50" disabled={isUploading}>{isUploading ? <Loader2 className="animate-spin mx-auto" size={20}/> : (isDiveModal.entry ? '수정 완료' : '로그 저장')}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Trophy, Calendar, MapPin, Users, ChevronLeft, Trash2, Camera, 
  Play, Cloud, CloudOff, Loader2, ExternalLink, Globe, User as UserIcon, 
  LogOut, Edit2, Check, X, Search, Clock, Award, ShieldCheck, RefreshCw,
  BrainCircuit, Activity, Lightbulb, Sparkles
} from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { Discipline, DiveSession, DiveEntry, MediaFile, PersonalBest, User } from './types';
import { formatTime, calculateOverallPB, calculateSessionPB, fileToBase64, parseSmartTime } from './utils';

const DRIVE_FOLDER_ID = '1Kcx0f-fqKsnYzof58Gg5gMZfKaeg4e_x';
const CLIENT_ID = '229707401391-cfovrjr2ecse3vk4jv613pkgi3mmmn0a.apps.googleusercontent.com'; 
const SCOPES = 'https://www.googleapis.com/auth/drive.file';

const LOCATIONS = ["딥스테이션", "올림픽공원 수영장", "성남 아쿠아라인"];
const ORGS = ["AIDA", "PADI", "SSI", "기타"];
const LEVELS = ["Level 1", "Level 2", "Level 3", "Level 4", "Instructor"];

// --- Sub-components ---

