              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-600 uppercase ml-1 tracking-widest">Location</label>
                <div className="grid grid-cols-1 gap-2">
                  <input required id="loc-input" type="text" name="location" placeholder="다이빙 포인트" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-2xl px-5 py-4 text-sm outline-none focus:border-purple-500 transition-all" />
                  <div className="flex flex-wrap gap-2">
                    {LOCATIONS.map(loc => (
                      <button key={loc} type="button" onClick={() => { (document.getElementById('loc-input') as HTMLInputElement).value = loc; }} className="text-[10px] font-black bg-[#2d2d3a] px-3 py-2 rounded-xl hover:bg-purple-600 transition-colors">{loc}</button>
                    ))}
                  </div>
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-600 uppercase ml-1 tracking-widest">Buddy</label>
                <input required type="text" name="buddy" placeholder="버디 이름" className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-2xl px-5 py-4 text-sm outline-none focus:border-purple-500" />
              </div>
              <textarea name="note" placeholder="오늘의 다이빙 메모" rows={2} className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-2xl px-5 py-4 text-sm outline-none resize-none focus:border-purple-500"></textarea>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsNewSessionModal(false)} className="flex-1 font-bold text-gray-500">취소</button>
                <button type="submit" className="flex-[2] bg-purple-600 font-black text-white py-4 rounded-3xl shadow-lg shadow-purple-900/40">세션 시작</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Profile Edit Modal */}
      {isProfileEditModal && (
        <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-[#1a1a24] w-full max-w-sm rounded-[40px] p-8 border border-[#2d2d3a]">
            <h2 className="text-2xl font-black mb-8 flex items-center gap-2"><Award className="text-purple-500"/> 프로필 설정</h2>
            <form onSubmit={handleUpdateProfile} className="space-y-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-600 uppercase ml-1 tracking-widest">발급 단체</label>
                <select name="organization" defaultValue={currentUser?.organization || ORGS[0]} className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-2xl px-5 py-4 text-sm outline-none appearance-none focus:border-purple-500">
                  {ORGS.map(org => <option key={org} value={org}>{org}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-gray-600 uppercase ml-1 tracking-widest">레벨</label>
                <select name="level" defaultValue={currentUser?.level || LEVELS[0]} className="w-full bg-[#0f0f17] border border-[#2d2d3a] rounded-2xl px-5 py-4 text-sm outline-none appearance-none focus:border-purple-500">
                  {LEVELS.map(lv => <option key={lv} value={lv}>{lv}</option>)}
                </select>
              </div>
              <div className="flex items-center justify-between p-4 bg-[#0f0f17] border border-[#2d2d3a] rounded-2xl">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 bg-orange-500 rounded-full animate-pulse"/>
                  <span className="text-xs font-bold">다음 레벨 교육 중</span>
                </div>
                <input type="checkbox" name="isTraining" defaultChecked={currentUser?.isTraining} className="w-6 h-6 accent-purple-600" />
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsProfileEditModal(false)} className="flex-1 font-bold text-gray-500">취소</button>
