                                <button onClick={() => analyzeDive(entry)} className={`hover:text-blue-400 flex items-center gap-1 text-[10px] font-black border border-blue-500/30 px-2 py-1 rounded-lg ${isAnalyzing ? 'opacity-50 animate-pulse' : ''}`}>
